// Text Growth 1.3.0 source for Shape Train localized initial Guides.
// Localized route generation consumes this source; runtime shared Guide hydration is disabled for this owned Guide.
export const SHAPE_TRAIN_GUIDE_SECTIONS = Object.freeze({
  "en": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Shape Train game information\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay Kids Game Guide</span><h2 data-wp-game-title data-runtime-localize=\"off\">Shape Train</h2><p>Shape Train is a free bilingual Kids matching game with 30 saved routes and six Conductor Checks. Shape friends wait at a cheerful station while the player finds the train car with the same circle, square, triangle, star, diamond, or heart symbol. The opening routes are direct picture matches. Later chapters reduce color, move the car order after each boarding, briefly hide the passenger, or require the passenger to be selected before a car can accept the ticket. Route 30 combines all of those rules with all six cars. There is no countdown, life limit, purchase, account, advertising request, or penalty that ends a route.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>Shape matching</span><span>Outline recognition</span><span>Visual memory</span><span>Ordered boarding</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Gameplay</span><strong>Shape Sorting</strong></div><div class=\"game-info-fact\"><span>Genre</span><strong>Preschool · Education · Animal</strong></div><div class=\"game-info-fact\"><span>Difficulty</span><strong>Easy</strong></div><div class=\"game-info-fact\"><span>Estimated Play Time</span><strong>2-5 minutes per route</strong></div><div class=\"game-info-fact\"><span>Skills Trained</span><strong>Color Recognition · Logic · Hand-Eye Coordination</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>World and Mission</h3><p>The Shape Line links six small stations where animal friends deliver bright shape parcels. Every parcel carries one clear symbol, and every orange train car has a matching window. The player is the junior conductor responsible for checking the symbol and sending each passenger to the correct car. A completed route means every waiting friend is safely aboard and the train can leave the platform.</p>\n<p>The route rules represent busier parts of the railway. Outline Cars travel through fog that removes most color. Switching Cars arrive on moving platforms. Remember Passenger routes briefly lower the station card, while Boarding Pass routes require a passenger check before a car is chosen. Clearing Route 30 completes the final mixed Conductor Check.</p></div>\n      <div class=\"game-info-section\"><h3>How the Systems Work</h3><p>Each route contains four to eight passengers selected from six real shapes. Only one visible car matches the current passenger.</p>\n<p>A correct choice shows a short visible-time celebration, advances progress and presents the next passenger. A wrong car gives gentle feedback and leaves the same passenger available.</p>\n<p>Outline Cars reduce color so geometry matters. Switching Cars reorder after every correct match. Remember Passenger hides the symbol but allows a no-penalty reveal. Boarding Pass requires the passenger to be selected first.</p>\n<p>Zero retries awards three stars, a small number awards two, and additional retries award one. The Result Skill Report uses actual matches, first tries, retries and boarded passengers.</p>\n<p>Stars and the highest unlock stay only in this browser. There is no account, leaderboard, purchase, advertising request, life meter or countdown.</p>\n<p>Every fifth route is a Conductor Check. Route 30 saves the final result and exposes no Route 31.</p></div>\n      <div class=\"game-info-section\"><h3>How to Play</h3><ol><li>Press Start Game and swipe the horizontal route rail to an unlocked card.</li><li>Read the route rule and look at the passenger shape in the lower station card.</li><li>Tap the passenger, then choose the train car with the same symbol; drag, mouse and keyboard are also supported.</li><li>On memory routes, recall the hidden symbol or tap the passenger to reveal it again.</li><li>Board every listed passenger to save stars and unlock exactly the next route.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Strategy Tips</h3><ul><li>Say the shape name before choosing a car.</li><li>Compare points and curved edges when outline cars remove color.</li><li>Scan the whole track again after every match on a moving route.</li><li>For memory play, name the symbol aloud or trace its outline in the air.</li><li>On Boarding Pass routes, select the passenger before touching a car.</li><li>A wrong choice keeps the route open, so pause and compare instead of guessing quickly.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Campaign and Difficulty Growth</h3><p>Routes 1–5 teach Direct Match with two to four bright cars and end at the first Conductor Check.</p>\n<p>Routes 6–10 use Outline Cars, making curves, corners and points more important than color.</p>\n<p>Routes 11–15 use Switching Cars that reorder after a successful boarding.</p>\n<p>Routes 16–20 briefly hide the passenger; tapping it restores the same shape without a penalty.</p>\n<p>Routes 21–25 add the ordered Boarding Pass action before the shape match.</p>\n<p>Routes 26–30 combine prior rules. Route 30 uses six cars and eight passengers with outline, movement, memory and Boarding Pass rules.</p></div>\n      <div class=\"game-info-section\"><h3>Developer Design Note</h3><p>Difficulty grows by changing what the player observes instead of shrinking controls, adding a timer or hiding the correct hit area. Direct matching establishes the vocabulary; outline, movement, memory and ordered selection each add one understandable decision. The fixed logical layout scales uniformly on phone, tablet, desktop and short landscape. Image-backed cars and tokens keep play visual, while localized text explains only the current rule. Match and memory delays count visible play time, so an app switch cannot silently advance the route. Unlike Animal Quiz, no factual reading is required; unlike Zoo Helper Day, the decision is visual equivalence rather than care purpose. Kids play has no advertising, purchase, account, ranking or diagnostic claim.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Parent Note</h3><p>Shape Train may support conversations about circles, corners, points, visual matching, short recall, action order, focus and hand-eye coordination. An adult can name each shape aloud or ask how two outlines differ. Stars and the Skill Report describe only this play session; they are not a school grade, IQ score, developmental diagnosis or comparison with another child. Progress stays in the current browser and may disappear if local storage is cleared. No child profile is required, and the Kids route requests no advertising.</p></div>\n      <div class=\"game-info-section\"><h3>FAQ</h3><dl><div><dt>How many routes are included?</dt><dd>There are 30 saved routes in six chapters, with Conductor Checks at 5, 10, 15, 20, 25 and 30.</dd></div><div><dt>Which shapes appear?</dt><dd>The game uses circles, squares, triangles, stars, diamonds and hearts.</dd></div><div><dt>Why did the passenger disappear?</dt><dd>Remember Passenger routes briefly hide it. Tap the passenger to reveal the same shape again without a penalty.</dd></div><div><dt>Why did the train cars move?</dt><dd>Switching Cars routes reorder them after a correct match so the player scans again.</dd></div><div><dt>Why will a car not accept my choice?</dt><dd>Boarding Pass routes require the passenger to be selected before choosing a car.</dd></div><div><dt>What happens after a wrong match?</dt><dd>The same passenger remains available with gentle feedback.</dd></div><div><dt>Is progress saved?</dt><dd>Stars and the highest unlocked route are stored only in this browser; no login is required.</dd></div><div><dt>Does it support phones and keyboards?</dt><dd>Yes. Touch, drag, mouse and keyboard use the same matching rules.</dd></div><div><dt>Does the Kids page contain ads?</dt><dd>No. Shape Train creates no advertising request or ad reserve.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Related Games</h3><p data-related-intro>More gentle visual-matching games on WeightPlay:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/en/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Star Memory</strong><span>Remember where matching stars and symbols are hidden.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/en/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Color Lunchbox</strong><span>Match foods to the correct natural-color lunchbox.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"en\" data-runtime-localize=\"off\"><h3 data-compare-title>Similar preschool shape-matching reference</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC's Colors &amp; Shapes - Learn Color also teaches shape recognition through matching; its official App Store description includes matching activities where children pair shapes and outlines. Shape Train puts that visual decision inside one 30-route train campaign: six passenger shapes progress from direct matches to outline cars, changing car order, memory routes, and a boarding rule that asks the player to select the passenger first, with a Conductor Check every fifth route. There is no countdown or life limit, and stars plus the highest unlocked route stay in this browser.</p><p data-compare-disclaimer>Shape Train is an independent WeightPlay game, not an official Colors &amp; Shapes - Learn Color version. WeightPlay is not affiliated with, endorsed by, licensed by, or co-developed with RV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: Colors &amp; Shapes - Learn Color official App Store listing</a></p></article></section>",
  "zh-Hant": "<section class=\"game-page-info game-page-info-static\" aria-label=\"形狀小火車 遊戲資訊\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay 兒童遊戲指南</span><h2 data-wp-game-title data-runtime-localize=\"off\">形狀小火車</h2><p>《動物形狀小火車》是一款免費的雙語兒童配對遊戲，共有 30 條可保存路線與六次車長檢查。形狀朋友在明亮車站等候，玩家要從圓形、正方形、三角形、星形、菱形與愛心車廂中找出相同符號。前段是直接看圖配對；後續會淡化顏色、在每次上車後改變車廂順序、暫時藏起乘客，或要求先驗票再選車廂。第 30 路線會把所有規則與六種車廂合在一起。遊戲沒有倒數、生命限制、購買、帳號、廣告請求，也不會因一次選錯就結束路線。</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>形狀配對</span><span>輪廓辨識</span><span>記憶回想</span><span>順序上車</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>玩法</span><strong>形狀分類</strong></div><div class=\"game-info-fact\"><span>類型</span><strong>幼兒 · 教育 · 動物</strong></div><div class=\"game-info-fact\"><span>難度</span><strong>簡單</strong></div><div class=\"game-info-fact\"><span>預估遊玩時間</span><strong>每條路線 2–5 分鐘</strong></div><div class=\"game-info-fact\"><span>練習能力</span><strong>形狀辨識 · 邏輯 · 手眼協調</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>世界與任務</h3><p>形狀線連接六座小車站，動物朋友會帶著有清楚符號的彩色包裹來搭車，每節橘色車廂的窗戶都有對應形狀。玩家扮演小車長，負責檢查符號並把乘客送到正確車廂。完成一條路線，代表所有等候朋友都安全上車，列車可以出發。</p>\n<p>不同規則代表鐵路較忙碌的區段。輪廓車廂行經薄霧，移動車廂停在會切換位置的月台；記憶乘客會暫時收起車站卡；驗票路線則要求先確認乘客。通過第 30 路線，代表完成最後一次混合車長檢查。</p></div>\n      <div class=\"game-info-section\"><h3>遊戲系統</h3><p>每條路線有四到八名乘客，取自六種真實形狀；畫面上只會有一節車廂符合目前乘客。</p>\n<p>答對會顯示短暫的上車動畫、增加進度並換下一名乘客；選錯只會溫和提醒，同一名乘客仍可繼續嘗試。</p>\n<p>輪廓車廂降低顏色提示；移動車廂在答對後重新排序；記憶乘客會藏起符號但可免費再看；驗票規則要求先點乘客。</p>\n<p>零次重試可得三星，少量重試得二星，更多重試得一星。技能報告只使用本次真實配對、首次答對、重試與上車人數。</p>\n<p>星星與最高解鎖路線只保存在目前瀏覽器。沒有帳號、排行榜、購買、廣告、生命值或倒數。</p>\n<p>每五條路線是一個車長檢查；第 30 路線會保存最終結果，不會出現不存在的第 31 路線。</p></div>\n      <div class=\"game-info-section\"><h3>玩法說明</h3><ol><li>按下開始遊戲，在水平路線軌道上滑到已解鎖卡片。</li><li>閱讀路線規則，觀察下方車站卡中的乘客形狀。</li><li>先點乘客，再點相同符號的車廂；拖曳、滑鼠與鍵盤也能操作。</li><li>記憶路線可回想藏起的符號，或再點乘客把它顯示出來。</li><li>讓所有乘客上車即可保存星星，並只解鎖下一條路線。</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>策略提示</h3><ul><li>選車廂前先說出形狀名稱。</li><li>輪廓車廂沒有明顯顏色時，比較尖角、邊與曲線。</li><li>移動路線每次答對後都重新掃視整條軌道。</li><li>記憶遊玩可把符號說出來，或用手在空中描出輪廓。</li><li>驗票路線要先選乘客，再碰車廂。</li><li>選錯不會關閉路線，停一下重新比較即可。</li></ul></div>\n      <div class=\"game-info-section\"><h3>關卡與難度成長</h3><p>第 1–5 路線是直接配對，以二到四節明亮車廂介紹六種形狀，第 5 路線是首次車長檢查。</p>\n<p>第 6–10 路線使用輪廓車廂，曲線、角與尖端會比顏色更重要。</p>\n<p>第 11–15 路線加入移動車廂，每次成功上車後都會重新排序。</p>\n<p>第 16–20 路線會暫時藏起乘客；再點乘客即可無懲罰顯示同一形狀。</p>\n<p>第 21–25 路線加入先驗票、再配對的動作順序。</p>\n<p>第 26–30 路線混合舊規則；第 30 路線有六節車廂、八名乘客，並結合輪廓、移動、記憶與驗票。</p></div>\n      <div class=\"game-info-section\"><h3>開發設計理念</h3><p>難度成長來自改變玩家要觀察的線索，而不是縮小按鈕、增加壓力倒數或藏起正確點擊區。直接配對先建立形狀詞彙，輪廓、移動、記憶與順序再各加入一個能理解的判斷。固定邏輯畫面會在手機、平板、桌面與短橫向螢幕等比縮放；圖片車廂與形狀圖塊保留圖像為主的操作，文字只說明目前規則。配對與記憶等待只計算實際可見時間，切到其他 App 不會讓路線偷偷前進。它不像《動物知識小測》需要閱讀動物事實，也不像《動物園小幫手日》要依用途選照護工具；本作的核心始終是視覺等同。兒童遊玩沒有廣告、購買、帳號、排名或診斷宣稱。</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>家長說明</h3><p>《動物形狀小火車》可用來談圓形、角、尖端、視覺配對、短期記憶、動作順序、專注與手眼協調。大人可以一起說出形狀名稱，或問孩子兩個輪廓哪裡不同。星星與技能報告只描述這次遊玩，不是學校成績、智力分數、發展診斷，也不會與其他孩子比較。進度只留在目前瀏覽器，清除網站資料可能使它消失；不需要兒童帳號，Kids 路線也不會請求廣告。</p></div>\n      <div class=\"game-info-section\"><h3>常見問題</h3><dl><div><dt>共有多少條路線？</dt><dd>共有 30 條可保存路線與六個章節，車長檢查位於第 5、10、15、20、25、30 路線。</dd></div><div><dt>有哪些形狀？</dt><dd>遊戲實際使用圓形、正方形、三角形、星形、菱形與愛心。</dd></div><div><dt>乘客為什麼消失？</dt><dd>記憶乘客路線會暫時藏起它；再點乘客即可無懲罰顯示同一形狀。</dd></div><div><dt>車廂為什麼移動？</dt><dd>移動車廂會在答對後重新排序，讓玩家再次觀察。</dd></div><div><dt>車廂為什麼不接受選擇？</dt><dd>驗票路線要求先點乘客，再選車廂。</dd></div><div><dt>選錯會怎樣？</dt><dd>同一名乘客會留在畫面，玩家可在溫和提示後再試。</dd></div><div><dt>進度會保存嗎？</dt><dd>星星與最高解鎖路線只保存在目前瀏覽器，不需要登入。</dd></div><div><dt>手機與鍵盤都能玩嗎？</dt><dd>可以，觸控、拖曳、滑鼠與鍵盤使用相同配對規則。</dd></div><div><dt>Kids 頁面有廣告嗎？</dt><dd>沒有，《動物形狀小火車》不會建立廣告請求或廣告保留區。</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>相關遊戲</h3><p data-related-intro>想繼續練習觀察與配對，可以玩：</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/zh-tw/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>星星翻牌</strong><span>記住星星與符號的位置，再找出成對圖案。</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/zh-tw/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>顏色便當盒</strong><span>依食物的自然顏色，把它送進正確便當盒。</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"zh-Hant\" data-runtime-localize=\"off\"><h3 data-compare-title>相似幼兒形狀配對玩法參考</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC 的 Colors &amp; Shapes - Learn Color 也以形狀辨識與配對為核心；官方 App Store 說明中的配對活動會讓孩子把形狀與輪廓對應起來。《形狀小火車》把這類視覺判斷放進 30 條小火車路線：六種乘客形狀會依序加入直接配對、輪廓車廂、車廂換位、記憶乘客與先選乘客再選車廂的驗票規則，每五條路線都有一次車長檢查。遊戲沒有倒數或生命限制，星星與最高解鎖路線只保存在目前瀏覽器。</p><p data-compare-disclaimer>《形狀小火車》是 WeightPlay 獨立製作的遊戲，不是 Colors &amp; Shapes - Learn Color 官方版本。WeightPlay 與 RV AppStudios LLC 沒有隸屬、背書、授權或共同開發關係。</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC：Colors &amp; Shapes - Learn Color 官方 App Store 頁面</a></p></article></section>",
  "zh-Hans": "<section class=\"game-page-info game-page-info-static\" aria-label=\"形状小火车 游戏信息\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay 儿童游戏指南</span><h2 data-wp-game-title data-runtime-localize=\"off\">形状小火车</h2><p>《动物形状小火车》是一款免费的双语儿童配对游戏，共有 30 条可保存路线与六次车长检查。形状朋友在明亮车站等候，玩家要从圆形、正方形、三角形、星形、菱形与爱心车厢中找出相同符号。前段是直接看图配对；后续会淡化颜色、在每次上车后改变车厢顺序、暂时藏起乘客，或要求先验票再选车厢。第 30 路线会把所有规则与六种车厢合在一起。游戏没有倒数、生命限制、购买、帐号、广告请求，也不会因一次选错就结束路线。</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>形状配对</span><span>轮廓辨识</span><span>记忆回想</span><span>顺序上车</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>玩法</span><strong>形状分类</strong></div><div class=\"game-info-fact\"><span>类型</span><strong>幼儿 · 教育 · 动物</strong></div><div class=\"game-info-fact\"><span>难度</span><strong>简单</strong></div><div class=\"game-info-fact\"><span>预估游玩时间</span><strong>每条路线 2–5 分钟</strong></div><div class=\"game-info-fact\"><span>练习能力</span><strong>形状辨识 · 逻辑 · 手眼协调</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>世界与任务</h3><p>形状线连接六座小车站，动物朋友会带著有清楚符号的彩色包裹来搭车，每节橘色车厢的窗户都有对应形状。玩家扮演小车长，负责检查符号并把乘客送到正确车厢。完成一条路线，代表所有等候朋友都安全上车，列车可以出发。</p>\n<p>不同规则代表铁路较忙碌的区段。轮廓车厢行经薄雾，移动车厢停在会切换位置的月台；记忆乘客会暂时收起车站卡；验票路线则要求先确认乘客。通过第 30 路线，代表完成最后一次混合车长检查。</p></div>\n      <div class=\"game-info-section\"><h3>游戏系统</h3><p>每条路线有四到八名乘客，取自六种真实形状；画面上只会有一节车厢符合目前乘客。</p>\n<p>答对会显示短暂的上车动画、增加进度并换下一名乘客；选错只会温和提醒，同一名乘客仍可继续尝试。</p>\n<p>轮廓车厢降低颜色提示；移动车厢在答对后重新排序；记忆乘客会藏起符号但可免费再看；验票规则要求先点乘客。</p>\n<p>零次重试可得三星，少量重试得二星，更多重试得一星。技能报告只使用本次真实配对、首次答对、重试与上车人数。</p>\n<p>星星与最高解锁路线只保存在目前浏览器。没有帐号、排行榜、购买、广告、生命值或倒数。</p>\n<p>每五条路线是一个车长检查；第 30 路线会保存最终结果，不会出现不存在的第 31 路线。</p></div>\n      <div class=\"game-info-section\"><h3>玩法说明</h3><ol><li>按下开始游戏，在水平路线轨道上滑到已解锁卡片。</li><li>阅读路线规则，观察下方车站卡中的乘客形状。</li><li>先点乘客，再点相同符号的车厢；拖曳、鼠标与键盘也能操作。</li><li>记忆路线可回想藏起的符号，或再点乘客把它显示出来。</li><li>让所有乘客上车即可保存星星，并只解锁下一条路线。</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>策略提示</h3><ul><li>选车厢前先说出形状名称。</li><li>轮廓车厢没有明显颜色时，比较尖角、边与曲线。</li><li>移动路线每次答对后都重新扫视整条轨道。</li><li>记忆游玩可把符号说出来，或用手在空中描出轮廓。</li><li>验票路线要先选乘客，再碰车厢。</li><li>选错不会关闭路线，停一下重新比较即可。</li></ul></div>\n      <div class=\"game-info-section\"><h3>关卡与难度成长</h3><p>第 1–5 路线是直接配对，以二到四节明亮车厢介绍六种形状，第 5 路线是首次车长检查。</p>\n<p>第 6–10 路线使用轮廓车厢，曲线、角与尖端会比颜色更重要。</p>\n<p>第 11–15 路线加入移动车厢，每次成功上车后都会重新排序。</p>\n<p>第 16–20 路线会暂时藏起乘客；再点乘客即可无惩罚显示同一形状。</p>\n<p>第 21–25 路线加入先验票、再配对的动作顺序。</p>\n<p>第 26–30 路线混合旧规则；第 30 路线有六节车厢、八名乘客，并结合轮廓、移动、记忆与验票。</p></div>\n      <div class=\"game-info-section\"><h3>开发设计理念</h3><p>难度成长来自改变玩家要观察的线索，而不是缩小按钮、增加压力倒数或藏起正确点击区。直接配对先建立形状词汇，轮廓、移动、记忆与顺序再各加入一个能理解的判断。固定逻辑画面会在手机、平板、桌面与短横向萤幕等比缩放；图片车厢与形状图块保留图像为主的操作，文字只说明目前规则。配对与记忆等待只计算实际可见时间，切到其他 App 不会让路线偷偷前进。它不像《动物知识小测》需要阅读动物事实，也不像《动物园小帮手日》要依用途选照护工具；本作的核心始终是视觉等同。儿童游玩没有广告、购买、帐号、排名或诊断宣称。</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>家长说明</h3><p>《动物形状小火车》可用来谈圆形、角、尖端、视觉配对、短期记忆、动作顺序、专注与手眼协调。大人可以一起说出形状名称，或问孩子两个轮廓哪里不同。星星与技能报告只描述这次游玩，不是学校成绩、智力分数、发展诊断，也不会与其他孩子比较。进度只留在目前浏览器，清除网站数据可能使它消失；不需要儿童帐号，Kids 路线也不会请求广告。</p></div>\n      <div class=\"game-info-section\"><h3>常见问题</h3><dl><div><dt>共有多少条路线？</dt><dd>共有 30 条可保存路线与六个章节，车长检查位于第 5、10、15、20、25、30 路线。</dd></div><div><dt>有哪些形状？</dt><dd>游戏实际使用圆形、正方形、三角形、星形、菱形与爱心。</dd></div><div><dt>乘客为什么消失？</dt><dd>记忆乘客路线会暂时藏起它；再点乘客即可无惩罚显示同一形状。</dd></div><div><dt>车厢为什么移动？</dt><dd>移动车厢会在答对后重新排序，让玩家再次观察。</dd></div><div><dt>车厢为什么不接受选择？</dt><dd>验票路线要求先点乘客，再选车厢。</dd></div><div><dt>选错会怎样？</dt><dd>同一名乘客会留在画面，玩家可在温和提示后再试。</dd></div><div><dt>进度会保存吗？</dt><dd>星星与最高解锁路线只保存在目前浏览器，不需要登录。</dd></div><div><dt>手机与键盘都能玩吗？</dt><dd>可以，触控、拖曳、鼠标与键盘使用相同配对规则。</dd></div><div><dt>Kids 页面有广告吗？</dt><dd>没有，《动物形状小火车》不会建立广告请求或广告保留区。</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>相关游戏</h3><p data-related-intro>想继续练习观察与配对，可以玩：</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/zh-cn/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>星星翻牌</strong><span>记住星星与符号的位置，再找出成对图案。</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/zh-cn/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>颜色便当盒</strong><span>按食物的自然颜色，把它送进正确便当盒。</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"zh-Hans\" data-runtime-localize=\"off\"><h3 data-compare-title>相似幼儿形状配对玩法参考</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC 的 Colors &amp; Shapes - Learn Color 也以形状辨识与配对为核心；官方 App Store 说明中的配对活动会让孩子把形状与轮廓对应起来。《形状小火车》把这类视觉判断放进 30 条小火车路线：六种乘客形状会依序加入直接配对、轮廓车厢、车厢换位、记忆乘客与先选乘客再选车厢的验票规则，每五条路线都有一次车长检查。游戏没有倒数或生命限制，星星与最高解锁路线只保存在目前浏览器。</p><p data-compare-disclaimer>《形状小火车》是 WeightPlay 独立制作的游戏，不是 Colors &amp; Shapes - Learn Color 官方版本。WeightPlay 与 RV AppStudios LLC 没有隶属、背书、授权或共同开发关系。</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC：Colors &amp; Shapes - Learn Color 官方 App Store 页面</a></p></article></section>",
  "ja": "<section class=\"game-page-info game-page-info-static\" aria-label=\"かたちトレイン ゲーム情報\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay ゲームガイド</span><h2 data-wp-game-title data-runtime-localize=\"off\">かたちトレイン</h2><p>かたちトレインは、形と車両を見分け、正しい場所へ運ぶ幼児向けパズルを楽しめるWeightPlayオリジナル作品です。画面に出る手がかりを読み、自分で次の一手を決めながら進めます。</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>かたち合わせ</span><span>輪郭認識</span><span>視覚記憶</span><span>手順操作</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>ゲーム内容</span><strong>形の仕分け</strong></div><div class=\"game-info-fact\"><span>ジャンル</span><strong>幼児 · 教育 · 動物</strong></div><div class=\"game-info-fact\"><span>難易度</span><strong>かんたん</strong></div><div class=\"game-info-fact\"><span>目安時間</span><strong>1ルート 2〜5 分</strong></div><div class=\"game-info-fact\"><span>身につく力</span><strong>色の見分け · 論理力 · 手と目の協調</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>世界とミッション</h3><p>この冒険では、プレイヤーが動物の仲間を助ける案内役になります。目的を達成するには、目の前の状況を観察し、急がずに選択の結果を確かめることが大切です。</p>\n<p>各ステージや場面には新しい条件が加わります。成功はただ先へ進むことではなく、仲間の世界を安全に整え、次の挑戦へつながる記録を残すことを意味します。</p></div>\n      <div class=\"game-info-section\"><h3>ゲームの仕組み</h3><p>1回のプレイでは、形と車両を見分け、正しい場所へ運ぶ幼児向けパズル。表示される目標、残りの機会、相手や障害物の動きを確認してから操作してください。</p>\n<p>進行すると新しい組み合わせ、道具、敵、またはルールが現れます。結果画面では達成内容を確認して、次へ進むか同じ課題をもう一度試せます。</p>\n<p>保存される進行はこのブラウザ内だけに残ります。ログインは必要ありません。</p></div>\n      <div class=\"game-info-section\"><h3>遊び方</h3><ol><li>メイン画面でスタートを選びます。</li><li>ステージがある作品では、開放済みのカードから挑戦を選びます。</li><li>画面のヒントと目標を読んで、タップ、ドラッグ、またはキーボードで操作します。</li><li>結果を確認し、次の挑戦またはリトライを選びます。</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>攻略のヒント</h3><ul><li>最初に目標と失敗条件を確認してから動きましょう。</li><li>一度に多くを急がず、手がかりが変わった場面で次の選択を考えましょう。</li><li>うまくいかなかった時は、直前の選択を見直して別の順番や位置を試しましょう。</li></ul></div>\n      <div class=\"game-info-section\"><h3>進行と難易度</h3><p>序盤は基本操作と読みやすい目標を紹介します。中盤からは複数の条件を組み合わせ、後半ではこれまで覚えた選択を続けて使う場面が増えます。</p>\n<p>数字だけを大きくするのではなく、観察、位置、順番、タイミングを使い分けるほど安定して進める構成です。</p></div>\n      <div class=\"game-info-section\"><h3>開発者メモ</h3><p>短いセッションでも、プレイヤー自身の判断が結果につながるよう設計しました。タッチ、マウス、キーボードで同じ目的に取り組め、画面の読みやすさと再挑戦のしやすさを大切にしています。</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>保護者向け</h3><p>このゲームはブラウザで遊べ、基本プレイにログインは必要ありません。進行やスコアはこの端末のブラウザに保存されます。表示される記録はゲーム内の振り返りであり、能力、医療、学習の正式な評価ではありません。</p></div>\n      <div class=\"game-info-section\"><h3>よくある質問</h3><dl><div><dt>無料で遊べますか？</dt><dd>はい。ブラウザで基本プレイを始められ、ログインは必要ありません。</dd></div><div><dt>進行は保存されますか？</dt><dd>対応する進行はこのブラウザにローカル保存されます。ブラウザのデータを消すと失われる場合があります。</dd></div><div><dt>スマートフォンでも遊べますか？</dt><dd>はい。タップとドラッグを使える画面に対応しています。</dd></div><div><dt>うまく進めない時は？</dt><dd>目標とヒントを確認し、位置、順番、またはタイミングを変えて再挑戦してください。</dd></div><div><dt>ゲームの記録は正式な能力テストですか？</dt><dd>いいえ。楽しむためのゲーム内記録であり、正式な評価ではありません。</dd></div><div><dt>アカウントは必要ですか？</dt><dd>いいえ。通常のプレイにアカウントは必要ありません。</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>関連ゲーム</h3><p data-related-intro>観察とマッチングを続けるなら：</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/ja/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>星空メモリー</strong><span>星や記号の位置を覚えてペアを探します。</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/ja/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>色べんとう</strong><span>食べ物の自然な色を見て正しいお弁当箱に分けます。</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"ja\" data-runtime-localize=\"off\"><h3 data-compare-title>似た幼児向け形合わせゲームの参考</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC の Colors &amp; Shapes - Learn Color も形の認識とマッチングを扱い、公式 App Store の説明では形と輪郭を対応させる遊びが紹介されています。かたちトレインは、この見比べる判断を 30 ルートの列車キャンペーンにまとめています。6 種類の乗客を、直接マッチ、輪郭車両、並び替わる車両、記憶ルート、乗客を先に選ぶ乗車手順へ段階的に進め、5 ルートごとに車掌チェックがあります。制限時間や残機はなく、星と最高解放ルートはこのブラウザだけに保存されます。</p><p data-compare-disclaimer>かたちトレインは WeightPlay が独立して制作したゲームで、Colors &amp; Shapes - Learn Color の公式版ではありません。WeightPlay は RV AppStudios LLC と提携、推薦、ライセンス、共同開発の関係にありません。</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC：Colors &amp; Shapes - Learn Color 公式 App Store ページ</a></p></article></section>",
  "ko": "<section class=\"game-page-info game-page-info-static\" aria-label=\"모양 기차 게임 정보\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay 어린이 게임 가이드</span><h2 data-wp-game-title data-runtime-localize=\"off\">모양 기차</h2><p>모양 기차은 30개의 저장된 경로와 6개의 지휘자 확인 기능을 갖춘 무료 이중 언어 어린이 매칭 게임입니다. 플레이어가 동일한 원, 사각형, 삼각형, 별, 다이아몬드 또는 하트 기호가 있는 열차 차량을 찾는 동안 Shape 친구들은 쾌활한 역에서 기다리고 있습니다. 시작 경로는 직접 그림 일치입니다. 이후 장에서는 색상을 줄이고, 탑승할 때마다 자동차 순서를 이동하고, 승객을 잠시 숨기거나, 자동차가 티켓을 수락하기 전에 승객을 선택하도록 요구합니다. 경로 30은 이러한 모든 규칙을 6대의 차량 모두와 결합합니다. 카운트다운, 수명 제한, 구매, 계정, 광고 요청 또는 경로 종료에 따른 페널티가 없습니다.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>모양 맞추기</span><span>윤곽 인식</span><span>시각 기억</span><span>순서 탑승</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>게임플레이</span><strong>모양 정렬</strong></div><div class=\"game-info-fact\"><span>장르</span><strong>유치원 · 교육 · 동물</strong></div><div class=\"game-info-fact\"><span>난이도</span><strong>쉬움</strong></div><div class=\"game-info-fact\"><span>예상 시간</span><strong>노선당 2~5분</strong></div><div class=\"game-info-fact\"><span>연습 능력</span><strong>색상 인식 · 논리 · 손과 눈의 협응</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>세계와 목표</h3><p>모양 노선은 여섯 개의 작은 역을 잇고, 동물 친구들은 또렷한 도형 표시가 붙은 꾸러미를 들고 찾아옵니다. 각 주황색 객차 창에는 대응하는 도형이 있습니다. 플레이어는 어린 차장이 되어 표시를 확인하고 승객을 맞는 객차로 보냅니다. 대기 중인 친구가 모두 안전하게 탑승하면 한 경로가 끝나고 기차가 출발합니다.</p>\n<p>경로 규칙은 철도의 가장 바쁜 부분을 나타냅니다. 개요 자동차는 대부분의 색상을 제거하는 안개 속을 이동합니다. 스위칭 자동차는 움직이는 플랫폼에 도착합니다. 승객 노선은 스테이션 카드를 잠시 낮추는 반면, 탑승권 노선은 차량을 선택하기 전에 승객 확인이 필요하다는 점을 기억하세요. 경로 30을 클리어하면 최종 혼합 도체 확인이 완료됩니다.</p></div>\n      <div class=\"game-info-section\"><h3>게임 시스템</h3><p>각 경로에는 6개의 실제 모양 중에서 선택된 4~8명의 승객이 포함됩니다. 보이는 차량 한 대만이 현재 승객과 일치합니다.</p>\n<p>올바른 선택은 짧은 가시적 축하를 표시하고 진행 상황을 진행하며 다음 승객을 소개합니다. 잘못된 차량은 부드러운 피드백을 제공하고 동일한 승객을 이용할 수 있게 합니다.</p>\n<p>개요 자동차는 색상을 줄여서 기하학이 중요합니다. 올바른 일치가 있을 때마다 자동차를 교체하여 순서를 변경합니다. 승객은 기호를 숨기지만 처벌 없이 공개할 수 있다는 점을 기억하십시오. 탑승권은 승객을 먼저 선택해야 합니다.</p>\n<p>제로 재시도는 별 3개를 부여하고, 소수의 재시도는 별 2개를 부여하며, 추가 재시도는 별 1개를 부여합니다. 결과 스킬 보고서에는 실제 경기, 첫 번째 시도, 재시도 및 탑승 승객이 사용됩니다.</p>\n<p>별과 가장 높은 잠금 해제는 이 브라우저에만 유지됩니다. 계정, 리더보드, 구매, 광고 요청, 수명 측정기 또는 카운트다운이 없습니다.</p>\n<p>다섯 번째 경로마다 도체 확인이 이루어집니다. 경로 30은 최종 결과를 저장하고 경로 31을 노출하지 않습니다.</p></div>\n      <div class=\"game-info-section\"><h3>게임 방법</h3><ol><li>게임 시작을 누르고 수평 경로 레일을 스와이프하여 잠금 해제된 카드를 찾으세요.</li><li>경로 규칙을 읽고 하단 역 카드의 승객 모양을 살펴보세요.</li><li>승객을 탭한 후 동일한 기호가 있는 열차를 선택하세요. 드래그, 마우스, 키보드도 지원됩니다.</li><li>메모리 경로에서 숨겨진 기호를 불러오거나 승객을 탭하여 다시 표시하세요.</li><li>목록의 모든 승객을 태워 별을 지키고 바로 다음 노선을 잠금 해제하세요.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>전략 팁</h3><ul><li>자동차를 선택하기 전에 모양 이름을 말해보세요.</li><li>윤곽선 자동차가 색상을 제거할 때 점과 곡선 모서리를 비교합니다.</li><li>이동 경로에서 매 경기가 끝난 후 전체 트랙을 다시 스캔하세요.</li><li>기억력 놀이를 위해서는 상징의 이름을 큰 소리로 부르거나 공중에서 윤곽선을 따라 그려보세요.</li><li>탑승권 경로에서는 차량을 만지기 전에 승객을 선택하세요.</li><li>잘못된 선택으로 인해 경로가 계속 열려 있으므로 빨리 추측하는 대신 일시 중지하고 비교하십시오.</li></ul></div>\n      <div class=\"game-info-section\"><h3>진행과 난이도</h3><p>경로 1~5는 2~4대의 밝은 자동차와의 직접 매치를 가르치고 첫 번째 차장 확인에서 끝납니다.</p>\n<p>6~10번 도로는 아웃라인 카(윤곽 객차)를 사용하므로 곡선, 모퉁이, 점을 색상보다 더 중요하게 만듭니다.</p>\n<p>11~15번 경로는 탑승 성공 후 순서가 변경되는 차량 교환을 사용합니다.</p>\n<p>16~20번 노선은 승객을 잠시 숨깁니다. 탭하면 페널티 없이 동일한 모양으로 복원됩니다.</p>\n<p>경로 21-25는 모양 일치 전에 주문한 탑승권 작업을 추가합니다.</p>\n<p>경로 26-30은 이전 규칙을 결합합니다. 경로 30은 개요, 이동, 기억 및 탑승권 규칙에 따라 차량 6대와 승객 8명을 사용합니다.</p></div>\n      <div class=\"game-info-section\"><h3>개발자 디자인 노트</h3><p>컨트롤을 축소하거나, 타이머를 추가하거나, 올바른 적중 영역을 숨기는 대신 플레이어가 관찰하는 내용을 변경하면 난이도가 높아집니다. 직접 매칭은 어휘를 설정합니다. 개요, 움직임, 기억 및 순서화된 선택은 각각 하나의 이해 가능한 결정을 추가합니다. 고정된 논리적 레이아웃은 휴대폰, 태블릿, 데스크톱 및 짧은 가로 모드에서 균일하게 확장됩니다. 이미지 기반 자동차와 토큰은 시각적으로 계속 재생되며 현지화된 텍스트는 현재 규칙만 설명합니다. 매치 및 메모리 지연은 표시되는 플레이 시간을 계산하므로 앱 스위치가 자동으로 경로를 진행할 수 없습니다. 동물 퀴즈와 달리 사실에 근거한 읽기가 필요하지 않습니다. 동물원 도우미의 날과 달리 결정은 돌봄 목적보다는 시각적 동등성에 따라 결정됩니다. 키즈 플레이에는 광고, 구매, 계정, 순위 또는 진단 청구가 없습니다.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>보호자 안내</h3><p>동물 모양 기차는 원, 모서리, 점, 시각적 일치, 짧은 회상, 동작 순서, 초점 및 손과 눈의 협응에 대한 대화를 지원할 수 있습니다. 어른은 각 모양의 이름을 큰 소리로 말하거나 두 윤곽선이 어떻게 다른지 물어볼 수 있습니다. 스타와 스킬 보고서는 이 플레이 세션만 설명합니다. 이는 학교 성적, IQ 점수, 발달 진단 또는 다른 어린이와의 비교가 아닙니다. 진행 상황은 현재 브라우저에 유지되며 로컬 저장소가 지워지면 사라질 수 있습니다. 어린이 프로필은 필요하지 않으며 어린이 경로는 광고를 요청하지 않습니다.</p></div>\n      <div class=\"game-info-section\"><h3>자주 묻는 질문</h3><dl><div><dt>경로는 몇 개 있나요?</dt><dd>6개의 챕터에 30개의 저장된 경로가 있으며 5, 10, 15, 20, 25 및 30에 도체 확인이 있습니다.</dd></div><div><dt>어떤 모양이 나타납니까?</dt><dd>이 게임은 원, 사각형, 삼각형, 별, 다이아몬드 및 하트를 사용합니다.</dd></div><div><dt>승객은 왜 사라졌나요?</dt><dd>여객 노선은 잠시 숨겨두세요. 승객을 탭하면 페널티 없이 같은 모양이 다시 나타납니다.</dd></div><div><dt>기차칸은 왜 움직였나요?</dt><dd>자동차 경로를 전환하면 플레이어가 다시 검색할 수 있도록 올바른 일치 후에 경로 순서가 변경됩니다.</dd></div><div><dt>자동차는 왜 내 선택을 받아들이지 않을까?</dt><dd>탑승권 노선은 차량을 선택하기 전에 승객을 선택해야 합니다.</dd></div><div><dt>잘못된 일치 후에는 어떻게 되나요?</dt><dd>동일한 승객이 부드러운 피드백을 받을 수 있습니다.</dd></div><div><dt>진행 상황이 저장되나요?</dt><dd>별과 잠금 해제된 가장 높은 경로는 이 브라우저에만 저장됩니다. 로그인이 필요하지 않습니다.</dd></div><div><dt>휴대폰과 키보드를 지원하나요?</dt><dd>그렇습니다. 터치, 드래그, 마우스 및 키보드는 동일한 일치 규칙을 사용합니다.</dd></div><div><dt>키즈 페이지에 광고가 포함되어 있나요?</dt><dd>아니요. 동물 모양 기차는 광고 요청이나 광고 예약을 생성하지 않습니다.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>관련 게임</h3><p data-related-intro>관찰과 맞추기를 더 연습하려면:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/ko/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>별 메모리</strong><span>별과 기호의 위치를 기억해 같은 짝을 찾습니다.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/ko/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>색 도시락</strong><span>음식의 자연스러운 색을 보고 알맞은 도시락에 넣습니다.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"ko\" data-runtime-localize=\"off\"><h3 data-compare-title>비슷한 유아 모양 맞추기 게임 참고</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC의 Colors &amp; Shapes - Learn Color도 모양 인식과 맞추기를 다루며, 공식 App Store 설명에는 모양과 윤곽을 짝짓는 활동이 소개됩니다. 모양 기차는 이 시각적 판단을 30개 기차 경로로 구성합니다. 여섯 가지 승객 모양은 직접 맞추기, 윤곽 차량, 바뀌는 차량 순서, 기억 경로, 승객을 먼저 고르는 탑승 순서 규칙으로 발전하며 5개 경로마다 차장 확인이 있습니다. 제한 시간이나 생명 수는 없고, 별과 최고 해금 경로는 현재 브라우저에만 저장됩니다.</p><p data-compare-disclaimer>모양 기차는 WeightPlay가 독립적으로 만든 게임이며 Colors &amp; Shapes - Learn Color의 공식 버전이 아닙니다. WeightPlay는 RV AppStudios LLC와 제휴, 보증, 라이선스 또는 공동 개발 관계가 없습니다.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: Colors &amp; Shapes - Learn Color 공식 App Store 페이지</a></p></article></section>",
  "es": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Información de Tren de Formas\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">Guía de juegos Kids de WeightPlay</span><h2 data-wp-game-title data-runtime-localize=\"off\">Tren de Formas</h2><p>Tren de Formas es un juego de combinación bilingüe gratuito para niños con 30 rutas guardadas y seis controles de conductor. Los amigos de las formas esperan en una alegre estación mientras el jugador encuentra el vagón del tren con el mismo símbolo de círculo, cuadrado, triángulo, estrella, diamante o corazón. Las rutas de apertura son coincidencias de imágenes directas. Los capítulos posteriores reducen el color, cambian el orden de los automóviles después de cada embarque, ocultan brevemente al pasajero o requieren que se seleccione al pasajero antes de que un automóvil pueda aceptar el boleto. La Ruta 30 combina todas esas reglas con los seis autos. No existe cuenta atrás, límite de vida, compra, cuenta, solicitud de publicidad ni penalización que finalice una ruta.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>asociación de formas</span><span>reconocimiento de contornos</span><span>memoria visual</span><span>embarque por pasos</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Jugabilidad</span><strong>Clasificación de formas</strong></div><div class=\"game-info-fact\"><span>Género</span><strong>preescolar · Educación · animales</strong></div><div class=\"game-info-fact\"><span>Dificultad</span><strong>Fácil</strong></div><div class=\"game-info-fact\"><span>Tiempo estimado</span><strong>2-5 minutos por ruta</strong></div><div class=\"game-info-fact\"><span>Habilidades</span><strong>Reconocimiento de colores · Lógica · Coordinación mano-ojo</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Mundo y misión</h3><p>Shape Line une seis pequeñas estaciones donde los amigos animales entregan paquetes de formas brillantes. Cada paquete lleva un símbolo claro y cada vagón de tren naranja tiene una ventana correspondiente. El jugador es el conductor junior responsable de comprobar el símbolo y enviar a cada pasajero al vagón correcto. Una ruta completa significa que todos los amigos que esperan están a salvo a bordo y el tren puede salir del andén.</p>\n<p>Las reglas de ruta representan partes más transitadas del ferrocarril. Contorno Los autos viajan a través de una niebla que elimina la mayor parte del color. Los coches que cambian llegan en plataformas móviles. Recuerde Las rutas de pasajeros reducen brevemente la tarjeta de la estación, mientras que las rutas de tarjeta de embarque requieren una verificación de pasajero antes de elegir un automóvil. Al superar la Ruta 30 se completa la verificación final del conductor mixto.</p></div>\n      <div class=\"game-info-section\"><h3>Sistemas del juego</h3><p>Cada ruta contiene de cuatro a ocho pasajeros seleccionados entre seis formas reales. Sólo un coche visible coincide con el pasajero actual.</p>\n<p>Una elección correcta muestra una breve celebración en tiempo visible, avanza el progreso y presenta al siguiente pasajero. Un coche equivocado da una respuesta amable y deja al mismo pasajero disponible.</p>\n<p>Los coches de contorno reducen el color para que la geometría importe. Cambiar de coche se reordena después de cada coincidencia correcta. Recuerde que Pasajero oculta el símbolo pero permite revelarlo sin penalización. La tarjeta de embarque requiere que el pasajero sea seleccionado primero.</p>\n<p>Los intentos cero otorgan tres estrellas, un número pequeño otorga dos y los reintentos adicionales otorgan una. El Informe de habilidades de resultados utiliza coincidencias reales, primeros intentos, reintentos y pasajeros abordados.</p>\n<p>Las estrellas y el desbloqueo más alto permanecen solo en este navegador. No hay cuenta, tabla de clasificación, compra, solicitud de publicidad, medidor de vida ni cuenta regresiva.</p>\n<p>Cada quinta ruta es una verificación del conductor. La ruta 30 guarda el resultado final y no expone la ruta 31.</p></div>\n      <div class=\"game-info-section\"><h3>Cómo jugar</h3><ol><li>Presiona Iniciar juego y desliza el riel de ruta horizontal hacia una tarjeta desbloqueada.</li><li>Lea la regla de ruta y observe la forma del pasajero en la tarjeta de la estación inferior.</li><li>Toque al pasajero, luego elija el vagón de tren con el mismo símbolo; También se admiten arrastrar, mouse y teclado.</li><li>En rutas de memoria, recupera el símbolo oculto o toca al pasajero para revelarlo nuevamente.</li><li>Sube a bordo de todos los pasajeros de la lista para ahorrar estrellas y desbloquear exactamente la siguiente ruta.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Consejos</h3><ul><li>Di el nombre de la forma antes de elegir un coche.</li><li>Compare puntos y bordes curvos cuando los contornos de los automóviles eliminen el color.</li><li>Escanea toda la pista nuevamente después de cada partido en una ruta en movimiento.</li><li>Para jugar a la memoria, nombra el símbolo en voz alta o traza su contorno en el aire.</li><li>En rutas con tarjeta de embarque, seleccione al pasajero antes de tocar un automóvil.</li><li>Una elección incorrecta mantiene la ruta abierta, así que haga una pausa y compare en lugar de adivinar rápidamente.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Progreso y dificultad</h3><p>Las rutas 1 a 5 enseñan Direct Match con dos a cuatro autos brillantes y terminan en el primer Conductor Check.</p>\n<p>Las rutas 6 a 10 utilizan Vagones de contorno, lo que hace que las curvas, esquinas y puntos sean más importantes que el color.</p>\n<p>Las rutas 11 a 15 utilizan vagones de cambio que se reordenan después de un abordaje exitoso.</p>\n<p>Las rutas 16 a 20 ocultan brevemente al pasajero; al tocarlo se restaura la misma forma sin penalización.</p>\n<p>Las rutas 21 a 25 agregan la acción ordenada de la tarjeta de embarque antes de que coincida la forma.</p>\n<p>Las rutas 26 a 30 combinan reglas anteriores. La Ruta 30 utiliza seis automóviles y ocho pasajeros con reglas de contorno, movimiento, memoria y tarjeta de embarque.</p></div>\n      <div class=\"game-info-section\"><h3>Nota de diseño</h3><p>La dificultad aumenta al cambiar lo que el jugador observa en lugar de reducir los controles, agregar un temporizador u ocultar el área de impacto correcta. La coincidencia directa establece el vocabulario; El contorno, el movimiento, la memoria y la selección ordenada añaden cada uno una decisión comprensible. El diseño lógico fijo se escala uniformemente en teléfonos, tabletas, computadoras de escritorio y paisajes cortos. Los autos y fichas respaldados por imágenes mantienen el juego visual, mientras que el texto localizado explica solo la regla actual. Los retrasos en los partidos y en la memoria cuentan el tiempo de juego visible, por lo que un cambio de aplicación no puede avanzar silenciosamente en la ruta. A diferencia de Animal Quiz, no se requiere lectura objetiva; a diferencia del Día del Ayudante del Zoológico, la decisión es una equivalencia visual más que un propósito de cuidado. Kids Play no tiene publicidad, compra, cuenta, clasificación o reclamo de diagnóstico.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Nota para familias</h3><p>Tren de Formas puede respaldar conversaciones sobre círculos, esquinas, puntos, correspondencia visual, recuerdos breves, orden de acción, concentración y coordinación mano-ojo. Un adulto puede nombrar cada forma en voz alta o preguntar en qué se diferencian dos contornos. Las estrellas y el Informe de habilidades describen únicamente esta sesión de juego; no son una calificación escolar, un puntaje de coeficiente intelectual, un diagnóstico de desarrollo o una comparación con otro niño. El progreso permanece en el navegador actual y puede desaparecer si se borra el almacenamiento local. No se requiere perfil infantil y la ruta Kids no solicita publicidad.</p></div>\n      <div class=\"game-info-section\"><h3>Preguntas frecuentes</h3><dl><div><dt>¿Cuántas rutas están incluidas?</dt><dd>Hay 30 rutas guardadas en seis capítulos, con controles del conductor en 5, 10, 15, 20, 25 y 30.</dd></div><div><dt>¿Qué formas aparecen?</dt><dd>El juego utiliza círculos, cuadrados, triángulos, estrellas, diamantes y corazones.</dd></div><div><dt>¿Por qué desapareció el pasajero?</dt><dd>Recuerde que las rutas de pasajeros lo ocultan brevemente. Toca al pasajero para revelar la misma forma nuevamente sin penalización.</dd></div><div><dt>¿Por qué se movieron los vagones del tren?</dt><dd>Las rutas de Vagones cambiantes se reordenan después de una coincidencia correcta para que el jugador escanee nuevamente.</dd></div><div><dt>¿Por qué un coche no acepta mi elección?</dt><dd>Las rutas con tarjeta de embarque requieren que el pasajero sea seleccionado antes de elegir un automóvil.</dd></div><div><dt>¿Qué pasa después de un partido equivocado?</dt><dd>El mismo pasajero permanece disponible con una suave respuesta.</dd></div><div><dt>¿Se guarda el progreso?</dt><dd>Las estrellas y la ruta más alta desbloqueada se almacenan únicamente en este navegador; no es necesario iniciar sesión.</dd></div><div><dt>¿Es compatible con teléfonos y teclados?</dt><dd>Sí. Tocar, arrastrar, usar el mouse y el teclado usan las mismas reglas de coincidencia.</dd></div><div><dt>¿La página para niños contiene anuncios?</dt><dd>No. Tren de Formas no crea ninguna solicitud de publicidad ni reserva de publicidad.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Juegos relacionados</h3><p data-related-intro>Para seguir practicando observación y asociación:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/es/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Memoria Estelar</strong><span>Recuerda dónde están las estrellas y los símbolos para encontrar parejas.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/es/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Lonchera de Colores</strong><span>Relaciona alimentos con la lonchera de su color natural.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"es\" data-runtime-localize=\"off\"><h3 data-compare-title>Referencia de juego infantil similar de formas</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color, de RV AppStudios LLC, también trabaja el reconocimiento y la asociación de formas; la descripción oficial de App Store incluye actividades para emparejar formas y contornos. Tren de Formas lleva esa decisión visual a una campaña de 30 rutas: seis formas de pasajeros pasan por coincidencia directa, vagones de contorno, cambios de orden, memoria y una regla de embarque en la que se selecciona primero al pasajero, con una revisión del conductor cada cinco rutas. No hay cuenta atrás ni vidas, y las estrellas y la ruta más alta desbloqueada se guardan solo en este navegador.</p><p data-compare-disclaimer>Tren de Formas es un juego independiente de WeightPlay, no una versión oficial de Colors &amp; Shapes - Learn Color. WeightPlay no está afiliado, respaldado, autorizado ni desarrollado conjuntamente con RV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: ficha oficial de Colors &amp; Shapes - Learn Color en App Store</a></p></article></section>",
  "pt-BR": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Informações de Trem em forma de\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">Guia original do WeightPlay</span><h2 data-wp-game-title data-runtime-localize=\"off\">Trem em forma de</h2><p>Trem em forma de é um jogo de combinação infantil bilíngue gratuito com 30 rotas salvas e seis verificações de condutor. Os amigos da forma esperam em uma estação alegre enquanto o jogador encontra o vagão com o mesmo símbolo de círculo, quadrado, triângulo, estrela, diamante ou coração. As rotas de abertura são correspondências diretas de imagens. Os capítulos posteriores reduzem a cor, mudam a ordem do carro após cada embarque, ocultam brevemente o passageiro ou exigem que o passageiro seja selecionado antes que o carro possa aceitar a passagem. A Rota 30 combina todas essas regras com todos os seis carros. Não há contagem regressiva, limite de vida, compra, conta, solicitação de publicidade ou penalidade que encerre uma rota.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>associação de formas</span><span>reconhecimento de contornos</span><span>memória visual</span><span>embarque em sequência</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Jogabilidade</span><strong>Classificação de formas</strong></div><div class=\"game-info-fact\"><span>Gênero</span><strong>Pré-escola · Educação · Animais</strong></div><div class=\"game-info-fact\"><span>Dificuldade</span><strong>Fácil</strong></div><div class=\"game-info-fact\"><span>Tempo estimado</span><strong>2-5 minutos por rota</strong></div><div class=\"game-info-fact\"><span>Habilidades</span><strong>Reconhecimento de cores · Lógica · Coordenação mão-olho</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Mundo e missão</h3><p>A Linha das Formas liga seis pequenas estações onde amigos animais chegam com pacotes marcados por formas bem visíveis. Cada vagão laranja tem uma janela com a forma correspondente. O jogador é o pequeno condutor que confere o símbolo e envia cada passageiro ao vagão correto. A rota termina quando todos os amigos que aguardavam embarcam com segurança e o trem pode partir.</p>\n<p>As regras de rota representam as partes mais movimentadas da ferrovia. Contorno Os carros viajam em meio à neblina que remove a maior parte das cores. Os carros de troca chegam em plataformas móveis. Lembre-se: As rotas de passageiros baixam brevemente o cartão da estação, enquanto as rotas do cartão de embarque exigem uma verificação dos passageiros antes de um carro ser escolhido. A limpeza da Rota 30 conclui a verificação final do condutor misto.</p></div>\n      <div class=\"game-info-section\"><h3>Sistemas do jogo</h3><p>Cada rota contém de quatro a oito passageiros selecionados entre seis formas reais. Apenas um carro visível corresponde ao passageiro atual.</p>\n<p>Uma escolha correta mostra uma comemoração curta em tempo visível, avança o progresso e apresenta o próximo passageiro. Um carro errado dá um feedback gentil e deixa o mesmo passageiro disponível.</p>\n<p>Os carros de contorno reduzem a cor, portanto a geometria é importante. A troca de carros é reordenada após cada correspondência correta. Lembre-se de que o Passageiro esconde o símbolo, mas permite uma revelação sem penalidade. O cartão de embarque exige que o passageiro seja selecionado primeiro.</p>\n<p>Zero tentativas concedem três estrelas, um pequeno número concede duas e tentativas adicionais concedem uma. O Relatório de Habilidade de Resultado usa correspondências reais, primeiras tentativas, novas tentativas e passageiros embarcados.</p>\n<p>As estrelas e o desbloqueio mais alto ficam apenas neste navegador. Não há conta, tabela de classificação, compra, solicitação de publicidade, medidor de vida ou contagem regressiva.</p>\n<p>Cada quinta rota é uma verificação do condutor. O Rota 30 salva o resultado final e não expõe o Rota 31.</p></div>\n      <div class=\"game-info-section\"><h3>Como jogar</h3><ol><li>Pressione Iniciar Jogo e deslize o trilho horizontal para um cartão desbloqueado.</li><li>Leia a regra da rota e observe o formato do passageiro no cartão da estação inferior.</li><li>Toque no passageiro e escolha o vagão com o mesmo símbolo; arrastar, mouse e teclado também são suportados.</li><li>Nas rotas de memória, recupere o símbolo oculto ou toque no passageiro para revelá-lo novamente.</li><li>Embarque em todos os passageiros listados para salvar estrelas e desbloquear exatamente a próxima rota.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Dicas de estratégia</h3><ul><li>Diga o nome do formato antes de escolher um carro.</li><li>Compare pontos e bordas curvas quando os carros de contorno removem a cor.</li><li>Analise toda a pista novamente após cada partida em uma rota móvel.</li><li>Para brincar com a memória, nomeie o símbolo em voz alta ou trace seu contorno no ar.</li><li>Nas rotas do cartão de embarque, selecione o passageiro antes de tocar no carro.</li><li>Uma escolha errada mantém o caminho aberto, então faça uma pausa e compare em vez de adivinhar rapidamente.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Progresso e dificuldade</h3><p>As Rotas 1 a 5 ensinam Partida Direta com dois a quatro carros brilhantes e terminam na primeira Verificação do Condutor.</p>\n<p>As rotas 6 a 10 usam vagões de contorno, tornando curvas, cantos e pontos mais importantes que a cor.</p>\n<p>As rotas 11–15 usam carros de troca que são reordenados após um embarque bem-sucedido.</p>\n<p>As rotas 16–20 escondem brevemente o passageiro; tocar nele restaura a mesma forma sem penalidade.</p>\n<p>As rotas 21–25 adicionam a ação ordenada do cartão de embarque antes da correspondência de formato.</p>\n<p>As rotas 26–30 combinam regras anteriores. A Rota 30 utiliza seis carros e oito passageiros com regras de contorno, movimento, memória e cartão de embarque.</p></div>\n      <div class=\"game-info-section\"><h3>Nota de design</h3><p>A dificuldade aumenta mudando o que o jogador observa em vez de diminuir os controles, adicionar um cronômetro ou ocultar a área de acerto correta. A correspondência direta estabelece o vocabulário; contorno, movimento, memória e seleção ordenada acrescentam, cada um, uma decisão compreensível. O layout lógico fixo é dimensionado uniformemente em telefone, tablet, desktop e paisagem curta. Carros e fichas apoiados em imagens mantêm o visual do jogo, enquanto o texto localizado explica apenas a regra atual. Os atrasos de correspondência e memória contam o tempo de jogo visível, portanto, uma troca de aplicativo não pode avançar silenciosamente a rota. Ao contrário do Animal Quiz, nenhuma leitura factual é necessária; ao contrário do Zoo Helper Day, a decisão é a equivalência visual e não o propósito de cuidado. A brincadeira infantil não tem publicidade, compra, conta, classificação ou reivindicação de diagnóstico.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Nota para famílias</h3><p>Trem em forma de pode apoiar conversas sobre círculos, cantos, pontos, correspondência visual, recuperação curta, ordem de ação, foco e coordenação olho-mão. Um adulto pode nomear cada forma em voz alta ou perguntar como dois contornos diferem. As estrelas e o Relatório de Habilidade descrevem apenas esta sessão de jogo; não são notas escolares, pontuação de QI, diagnóstico de desenvolvimento ou comparação com outra criança. O progresso permanece no navegador atual e pode desaparecer se o armazenamento local for limpo. Nenhum perfil infantil é necessário e a rota infantil não solicita publicidade.</p></div>\n      <div class=\"game-info-section\"><h3>Perguntas frequentes</h3><dl><div><dt>Quantas rotas existem?</dt><dd>São 30 rotas salvas em seis capítulos, com Conductor Checks em 5, 10, 15, 20, 25 e 30.</dd></div><div><dt>Quais formas aparecem?</dt><dd>O jogo usa círculos, quadrados, triângulos, estrelas, diamantes e corações.</dd></div><div><dt>Por que o passageiro desapareceu?</dt><dd>Lembre-se de que as rotas de passageiros o escondem brevemente. Toque no passageiro para revelar a mesma forma novamente sem penalidade.</dd></div><div><dt>Por que os vagões do trem se moveram?</dt><dd>As rotas de troca de carros reordenam-nas após uma partida correta para que o jogador escaneie novamente.</dd></div><div><dt>Por que um carro não aceitará minha escolha?</dt><dd>As rotas do cartão de embarque exigem que o passageiro seja selecionado antes de escolher um carro.</dd></div><div><dt>O que acontece depois de uma partida errada?</dt><dd>O mesmo passageiro permanece disponível com feedback gentil.</dd></div><div><dt>O progresso é salvo?</dt><dd>As estrelas e a rota desbloqueada mais alta são armazenadas apenas neste navegador; nenhum login é necessário.</dd></div><div><dt>Suporta telefones e teclados?</dt><dd>Sim. Tocar, arrastar, mouse e teclado usam as mesmas regras de correspondência.</dd></div><div><dt>A página infantil contém anúncios?</dt><dd>Não. Trem em forma de não cria nenhuma solicitação de publicidade ou reserva de anúncios.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Jogos relacionados</h3><p data-related-intro>Para continuar praticando observação e associação:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/pt-br/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Memória de Estrela</strong><span>Lembre onde estão estrelas e símbolos para encontrar pares.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/pt-br/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Marmita Cor</strong><span>Associe alimentos à marmita da sua cor natural.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"pt-BR\" data-runtime-localize=\"off\"><h3 data-compare-title>Referência de jogo infantil semelhante de formas</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color, da RV AppStudios LLC, também trabalha reconhecimento e associação de formas; a descrição oficial da App Store inclui atividades para combinar formas com contornos. Trem em forma de leva essa decisão visual a uma campanha com 30 rotas: seis formas de passageiros avançam de correspondência direta para vagões de contorno, mudança da ordem dos vagões, memória e uma regra de embarque que pede selecionar primeiro o passageiro, com uma Verificação do Condutor a cada cinco rotas. Não há contagem regressiva nem vidas, e as estrelas e a rota mais alta desbloqueada ficam apenas neste navegador.</p><p data-compare-disclaimer>Trem em forma de é um jogo independente da WeightPlay, não uma versão oficial de Colors &amp; Shapes - Learn Color. A WeightPlay não é afiliada, endossada, licenciada nem desenvolvida em conjunto com a RV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: página oficial de Colors &amp; Shapes - Learn Color na App Store</a></p></article></section>",
  "fr": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Informations sur Le Train des Formes\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">Guide de jeu WeightPlay pour enfants</span><h2 data-wp-game-title data-runtime-localize=\"off\">Le Train des Formes</h2><p>Le Train des Formes Animales est un jeu bilingue gratuit d’association pour enfants avec 30 parcours sauvegardés et six Défis du conducteur. Des amis animaux attendent à une gare joyeuse. Le joueur cherche le wagon portant le même cercle, carré, triangle, étoile, losange ou cœur. Les premiers parcours sont des associations directes par l’image. Les chapitres suivants réduisent les couleurs, changent l’ordre des wagons après chaque embarquement, cachent brièvement le passager ou exigent de sélectionner le passager avant de choisir un wagon. Le parcours 30 réunit toutes les règles avec les six wagons. Il n’y a ni compte à rebours, ni vies, ni achat, ni compte, ni publicité, ni pénalité qui termine un parcours.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>association de formes</span><span>reconnaissance des contours</span><span>mémoire visuelle</span><span>embarquement séquencé</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Jeu</span><strong>Association de formes</strong></div><div class=\"game-info-fact\"><span>Genre</span><strong>Puzzle · Association · Jeu pour enfants</strong></div><div class=\"game-info-fact\"><span>Difficulté</span><strong>Facile</strong></div><div class=\"game-info-fact\"><span>Temps estimé</span><strong>2 à 5 minutes par parcours</strong></div><div class=\"game-info-fact\"><span>Compétences</span><strong>Reconnaissance des couleurs · Logique · Coordination œil-main</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Monde et mission</h3><p>La Ligne des Formes relie six petites gares où des amis animaux livrent des colis colorés. Chaque colis porte un symbole clair et chaque wagon orange possède une fenêtre correspondante. Le joueur est le jeune conducteur : il vérifie le symbole et envoie chaque passager dans le bon wagon. Quand tous les amis attendus sont à bord, le train peut quitter le quai.</p>\n<p>Les règles des parcours représentent les parties plus chargées du chemin de fer. Les Wagons en contour traversent un brouillard qui retire presque toutes les couleurs. Les Wagons mobiles arrivent sur des quais en mouvement. Les parcours de Mémoire du passager abaissent brièvement la carte de la gare, tandis que les parcours avec billet exigent de sélectionner le passager avant le wagon. Le parcours 30 termine le dernier Défi du conducteur mélangé.</p></div>\n      <div class=\"game-info-section\"><h3>Systèmes du jeu</h3><p>Chaque parcours contient quatre à huit passagers choisis parmi six formes réelles. Un seul wagon visible correspond au passager actuel.</p>\n<p>Un bon choix affiche une courte célébration, avance la progression et présente le passager suivant. Un mauvais wagon donne un retour bienveillant et laisse le même passager disponible.</p>\n<p>Les Wagons en contour réduisent les couleurs pour que la géométrie compte. Les Wagons mobiles changent d’ordre après chaque embarquement réussi. La Mémoire du passager cache le symbole mais permet de le révéler sans pénalité. Les parcours avec billet demandent de sélectionner le passager en premier.</p>\n<p>Zéro erreur rapporte trois étoiles, quelques erreurs deux et davantage d’erreurs une. Le Bilan des compétences utilise les associations réelles, les premiers essais, les erreurs et les passagers embarqués.</p>\n<p>Les étoiles et le parcours le plus avancé restent dans ce navigateur. Aucun compte, classement, achat, publicité, jauge de vies ou compte à rebours n’est nécessaire.</p>\n<p>Un parcours sur cinq est un Défi du conducteur. Le parcours 30 sauvegarde le dernier résultat et n’expose aucun parcours 31.</p></div>\n      <div class=\"game-info-section\"><h3>Comment jouer</h3><ol><li>Appuyez sur Jouer et faites glisser la ligne horizontale vers une carte débloquée.</li><li>Lisez la règle du parcours et observez la forme du passager sur la carte de gare inférieure.</li><li>Touchez le passager, puis choisissez le wagon portant le même symbole. Le glissement, la souris et le clavier sont également pris en charge.</li><li>Sur les parcours de mémoire, rappelez la forme cachée ou touchez le passager pour la révéler à nouveau.</li><li>Embarquez chaque passager pour sauvegarder les étoiles et débloquer exactement le parcours suivant.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Conseils</h3><ul><li>Dites le nom de la forme avant de choisir un wagon.</li><li>Comparez les pointes et les bords courbes lorsque les wagons en contour retirent les couleurs.</li><li>Scannez toute la voie après chaque association sur un parcours mobile.</li><li>Pour mémoriser, dites le symbole à voix haute ou dessinez son contour dans l’air.</li><li>Sur les parcours avec billet, sélectionnez le passager avant de toucher un wagon.</li><li>Une mauvaise réponse laisse le parcours ouvert : comparez calmement au lieu de deviner vite.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Progression et difficulté</h3><p>Les parcours 1 à 5 enseignent l’association directe avec deux à quatre wagons colorés et se terminent par le premier Défi du conducteur.</p>\n<p>Les parcours 6 à 10 utilisent les Wagons en contour : les courbes, les coins et les pointes deviennent plus importants que la couleur.</p>\n<p>Les parcours 11 à 15 utilisent les Wagons mobiles, qui changent d’ordre après une association réussie.</p>\n<p>Les parcours 16 à 20 cachent brièvement le passager ; le toucher révèle à nouveau la même forme sans pénalité.</p>\n<p>Les parcours 21 à 25 ajoutent l’action ordonnée du billet avant l’association de formes.</p>\n<p>Les parcours 26 à 30 combinent les règles précédentes. Le parcours 30 utilise six wagons et huit passagers avec contour, mouvement, mémoire et billet.</p></div>\n      <div class=\"game-info-section\"><h3>Note de conception</h3><p>La difficulté change ce que le joueur doit observer plutôt que de réduire les contrôles, d’ajouter un chronomètre ou de cacher la bonne zone. L’association directe installe le vocabulaire ; le contour, le mouvement, la mémoire et la sélection ordonnée ajoutent chacun une décision compréhensible. Le canevas logique fixe s’adapte proportionnellement au téléphone, à la tablette, au bureau et au paysage court. Les wagons et jetons illustrés gardent le jeu visuel, tandis que le texte localisé explique seulement la règle actuelle. Les pauses d’association et de mémoire comptent comme temps de jeu, de sorte qu’un changement d’application ne puisse pas avancer silencieusement le parcours. Contrairement à Animal Quiz, aucune lecture factuelle n’est requise : la décision est une équivalence visuelle, pas une intention de soin. Le jeu Kids n’a ni publicité, ni achat, ni compte, ni classement ni visée diagnostique.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Informations sur le joueur et la sauvegarde</h3><p>Le Train des Formes Animales peut soutenir des échanges sur les cercles, les coins, les pointes, la comparaison visuelle, la mémoire courte, l’ordre, l’attention et la coordination œil-main. Un adulte peut nommer chaque forme ou demander comment deux contours diffèrent. Les étoiles et le Bilan décrivent seulement cette partie ; ils ne sont ni une note scolaire, ni un score de QI, ni un diagnostic du développement, ni une comparaison avec un autre enfant. La progression reste dans ce navigateur et peut disparaître si les données locales sont effacées. Aucun profil d’enfant n’est nécessaire et la page Kids ne demande pas de publicité.</p></div>\n      <div class=\"game-info-section\"><h3>Questions fréquentes</h3><dl><div><dt>Combien de parcours sont inclus ?</dt><dd>Il y a 30 parcours sauvegardés dans six chapitres, avec des Défis du conducteur aux parcours 5, 10, 15, 20, 25 et 30.</dd></div><div><dt>Quelles formes apparaissent ?</dt><dd>Le jeu utilise des cercles, des carrés, des triangles, des étoiles, des losanges et des cœurs.</dd></div><div><dt>Pourquoi le passager a-t-il disparu ?</dt><dd>Les parcours de Mémoire du passager le cachent brièvement. Touchez-le pour révéler la même forme sans pénalité.</dd></div><div><dt>Pourquoi les wagons ont-ils bougé ?</dt><dd>Les Wagons mobiles changent d’ordre après une bonne association pour demander un nouveau balayage visuel.</dd></div><div><dt>Pourquoi un wagon n’accepte-t-il pas mon choix ?</dt><dd>Les parcours avec billet exigent de sélectionner le passager avant de choisir un wagon.</dd></div><div><dt>Que se passe-t-il après une mauvaise association ?</dt><dd>Le même passager reste disponible avec un retour bienveillant.</dd></div><div><dt>La progression est-elle sauvegardée ?</dt><dd>Les étoiles et le parcours le plus avancé sont sauvegardés uniquement dans ce navigateur ; aucun compte n’est requis.</dd></div><div><dt>Le jeu accepte-t-il les téléphones et les claviers ?</dt><dd>Oui. Le toucher, le glissement, la souris et le clavier utilisent les mêmes règles d’association.</dd></div><div><dt>La page Kids contient-elle des publicités ?</dt><dd>Non. Le Train des Formes Animales n’envoie aucune demande publicitaire et ne réserve aucun emplacement publicitaire.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Jeux associés</h3><p data-related-intro>Pour continuer à observer et associer :</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/fr/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Mémoire d'étoile</strong><span>Mémorise l’emplacement des étoiles et symboles pour retrouver les paires.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/fr/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Boîte à lunch couleur</strong><span>Associe les aliments à la boîte correspondant à leur couleur naturelle.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"fr\" data-runtime-localize=\"off\"><h3 data-compare-title>Référence de jeu de formes similaire pour enfants</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color de RV AppStudios LLC travaille aussi la reconnaissance et l’association des formes ; sa description officielle sur l’App Store présente des activités où l’enfant associe des formes à leurs contours. Le Train des Formes place cette décision visuelle dans une campagne de 30 parcours : six formes de passagers passent de l’association directe aux wagons en contour, au changement d’ordre, à la mémoire et à une règle d’embarquement où il faut d’abord sélectionner le passager, avec un Défi du conducteur tous les cinq parcours. Il n’y a ni compte à rebours ni vies, et les étoiles ainsi que le plus haut parcours débloqué restent dans ce navigateur.</p><p data-compare-disclaimer>Le Train des Formes est un jeu WeightPlay indépendant, et non une version officielle de Colors &amp; Shapes - Learn Color. WeightPlay n’est ni affilié, ni soutenu, ni licencié, ni codéveloppé avec RV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC : page App Store officielle de Colors &amp; Shapes - Learn Color</a></p></article></section>",
  "de": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Informationen zu Zug in Tierform\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay-Spielanleitung für Kinder</span><h2 data-wp-game-title data-runtime-localize=\"off\">Zug in Tierform</h2><p>Zug in Tierform ist ein kostenloses zweisprachiges Zuordnungsspiel für Kinder mit 30 gespeicherten Routen und sechs Schaffner-Checks. Tierfreunde warten an einer fröhlichen Station. Der Spieler findet den Waggon mit demselben Kreis-, Quadrat-, Dreieck-, Stern-, Rauten- oder Herzsymbol. Die ersten Routen sind direkte Bildvergleiche. Spätere Kapitel reduzieren die Farbe, ändern nach jedem Einstieg die Waggonreihenfolge, verstecken den Fahrgast kurz oder verlangen, dass der Fahrgast vor der Waggonwahl ausgewählt wird. Route 30 verbindet alle Regeln mit allen sechs Waggons. Es gibt keinen Countdown, keine Lebensbegrenzung, keinen Kauf, kein Konto, keine Werbung und keine Strafe, die eine Route beendet.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>Formen zuordnen</span><span>Umrisse erkennen</span><span>visuelles Gedächtnis</span><span>Boarding-Reihenfolge</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Spielweise</span><strong>Formen-Zuordnung</strong></div><div class=\"game-info-fact\"><span>Genre</span><strong>Puzzle · Zuordnung · Kinder</strong></div><div class=\"game-info-fact\"><span>Schwierigkeit</span><strong>Einfach</strong></div><div class=\"game-info-fact\"><span>Geschätzte Zeit</span><strong>2–5 Minuten pro Route</strong></div><div class=\"game-info-fact\"><span>Fähigkeiten</span><strong>Farberkennung · Logik · Hand-Auge-Koordination</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Welt und Mission</h3><p>Die Formenlinie verbindet sechs kleine Stationen, an denen Tierfreunde leuchtende Formpakete ausliefern. Jedes Paket trägt ein klares Symbol, und jeder orange Waggon hat ein passendes Fenster. Der Spieler ist der Junior-Schaffner: Er prüft das Symbol und schickt jeden Fahrgast in den richtigen Waggon. Wenn alle wartenden Freunde sicher eingestiegen sind, kann der Zug den Bahnsteig verlassen.</p>\n<p>Die Routenregeln zeigen anspruchsvollere Teile der Bahn. Umriss-Waggons fahren durch Nebel, der fast alle Farben entfernt. Wechsel-Waggons kommen auf beweglichen Bahnsteigen an. Bei Fahrgast-Merkrouten wird die Stationskarte kurz abgesenkt, während Boarding-Pass-Routen zuerst eine Fahrgastauswahl verlangen. Route 30 schließt den letzten gemischten Schaffner-Check ab.</p></div>\n      <div class=\"game-info-section\"><h3>Spielsysteme</h3><p>Jede Route enthält vier bis acht Fahrgäste aus sechs echten Formen. Nur ein sichtbarer Waggon passt zum aktuellen Fahrgast.</p>\n<p>Eine richtige Wahl zeigt eine kurze Feier, macht den Fortschritt weiter und stellt den nächsten Fahrgast vor. Ein falscher Waggon gibt freundliches Feedback; derselbe Fahrgast bleibt verfügbar.</p>\n<p>Umriss-Waggons reduzieren die Farbe, damit die Geometrie zählt. Wechsel-Waggons ordnen sich nach jedem richtigen Einstieg neu. Fahrgast-Merkrouten verstecken das Symbol, erlauben aber eine Aufdeckung ohne Strafe. Boarding-Pass-Routen verlangen zuerst die Auswahl des Fahrgasts.</p>\n<p>Null Fehlversuche geben drei Sterne, wenige Fehlversuche zwei und weitere Fehlversuche einen Stern. Der Ergebnisbericht verwendet echte Treffer, erste Versuche, Fehlversuche und eingestiegene Fahrgäste.</p>\n<p>Sterne und der höchste Freischaltstand bleiben in diesem Browser. Es gibt kein Konto, keine Rangliste, keinen Kauf, keine Werbung, keine Lebensanzeige und keinen Countdown.</p>\n<p>Jede fünfte Route ist ein Schaffner-Check. Route 30 speichert das letzte Ergebnis und zeigt keine Route 31.</p></div>\n      <div class=\"game-info-section\"><h3>So wird gespielt</h3><ol><li>Drücke Spiel starten und wische auf der waagerechten Routenleiste zu einer freigeschalteten Karte.</li><li>Lies die Routenregel und sieh dir das Formensymbol auf der unteren Stationskarte an.</li><li>Tippe auf den Fahrgast und wähle dann den Waggon mit demselben Symbol. Ziehen, Maus und Tastatur werden ebenfalls unterstützt.</li><li>Rufe auf Merkrouten das verborgene Symbol ab oder tippe auf den Fahrgast, um es erneut anzuzeigen.</li><li>Bringe alle aufgeführten Fahrgäste an Bord, um Sterne zu speichern und genau die nächste Route freizuschalten.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Strategietipps</h3><ul><li>Sage den Namen der Form, bevor du einen Waggon wählst.</li><li>Vergleiche Punkte und gebogene Kanten, wenn Umriss-Waggons die Farbe entfernen.</li><li>Scanne nach jedem Einstieg die ganze Strecke erneut, wenn sich die Waggons bewegen.</li><li>Nenne bei Merkrouten das Symbol laut oder zeichne seinen Umriss in der Luft nach.</li><li>Wähle bei Boarding-Pass-Routen zuerst den Fahrgast aus, bevor du einen Waggon berührst.</li><li>Eine falsche Wahl hält die Route offen. Vergleiche in Ruhe, statt schnell zu raten.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Fortschritt und Schwierigkeit</h3><p>Die Routen 1–5 lehren die direkte Zuordnung mit zwei bis vier leuchtenden Waggons und enden beim ersten Schaffner-Check.</p>\n<p>Die Routen 6–10 verwenden Umriss-Waggons. Kurven, Ecken und Spitzen werden wichtiger als die Farbe.</p>\n<p>Die Routen 11–15 verwenden Wechsel-Waggons, die sich nach einem erfolgreichen Einstieg neu ordnen.</p>\n<p>Die Routen 16–20 verstecken den Fahrgast kurz. Ein Tippen zeigt dieselbe Form ohne Strafe wieder.</p>\n<p>Die Routen 21–25 ergänzen die geordnete Boarding-Pass-Aktion vor dem Formenvergleich.</p>\n<p>Die Routen 26–30 verbinden die bisherigen Regeln. Route 30 nutzt sechs Waggons und acht Fahrgäste mit Umriss-, Bewegungs-, Merk- und Boarding-Pass-Regeln.</p></div>\n      <div class=\"game-info-section\"><h3>Designnotiz</h3><p>Die Schwierigkeit wächst durch veränderte Beobachtungsaufgaben, nicht durch kleinere Bedienelemente, einen Timer oder ein verstecktes Zielfeld. Direkte Zuordnung führt das Vokabular ein; Umriss, Bewegung, Erinnerung und die geordnete Auswahl ergänzen jeweils eine verständliche Entscheidung. Das feste logische Layout skaliert gleichmäßig auf Telefon, Tablet, Desktop und kurzer Queransicht. Bildgestützte Waggons und Fahrgäste halten das Spiel visuell, während lokalisierter Text nur die aktuelle Regel erklärt. Sichtbare Match- und Merkpausen zählen als Spielzeit, sodass ein App-Wechsel die Route nicht unbemerkt voranbringt. Anders als Tierquiz verlangt Zug in Tierform kein Faktenlesen: Die Entscheidung ist visuelle Gleichheit statt Pflegezweck. Das Kids-Spiel enthält keine Werbung, keinen Kauf, kein Konto, keine Rangliste und keine Diagnostik.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Spieler- und Speicherhinweise</h3><p>Zug in Tierform kann Gespräche über Kreise, Ecken, Spitzen, visuelles Vergleichen, kurzes Erinnern, Reihenfolgen, Aufmerksamkeit und Hand-Auge-Koordination unterstützen. Ein Erwachsener kann jede Form benennen oder fragen, wie sich zwei Umrisse unterscheiden. Sterne und der Ergebnisbericht beschreiben nur diese Spielrunde. Sie sind keine Schulnote, kein IQ-Wert, keine Entwicklungsdiagnose und kein Vergleich mit einem anderen Kind. Der Fortschritt bleibt in diesem Browser und kann beim Löschen lokaler Daten verschwinden. Ein Kinderprofil ist nicht erforderlich, und die Kids-Seite fordert keine Werbung an.</p></div>\n      <div class=\"game-info-section\"><h3>Häufige Fragen</h3><dl><div><dt>Wie viele Routen gibt es?</dt><dd>Es gibt 30 gespeicherte Routen in sechs Kapiteln mit Schaffner-Checks bei 5, 10, 15, 20, 25 und 30.</dd></div><div><dt>Welche Formen erscheinen?</dt><dd>Das Spiel verwendet Kreise, Quadrate, Dreiecke, Sterne, Rauten und Herzen.</dd></div><div><dt>Warum ist der Fahrgast verschwunden?</dt><dd>Auf Merkrouten wird er kurz versteckt. Tippe auf den Fahrgast, um dieselbe Form ohne Strafe wieder anzuzeigen.</dd></div><div><dt>Warum haben sich die Waggons bewegt?</dt><dd>Wechsel-Waggons ordnen sich nach einer richtigen Zuordnung neu, damit der Spieler erneut scannt.</dd></div><div><dt>Warum nimmt ein Waggon meine Wahl nicht an?</dt><dd>Boarding-Pass-Routen verlangen, dass der Fahrgast vor der Waggonwahl ausgewählt wird.</dd></div><div><dt>Was passiert nach einer falschen Zuordnung?</dt><dd>Der gleiche Fahrgast bleibt mit freundlichem Feedback verfügbar.</dd></div><div><dt>Wird der Fortschritt gespeichert?</dt><dd>Sterne und die höchste freigeschaltete Route werden nur in diesem Browser gespeichert; ein Login ist nicht nötig.</dd></div><div><dt>Unterstützt das Spiel Handys und Tastaturen?</dt><dd>Ja. Touch, Ziehen, Maus und Tastatur verwenden dieselben Zuordnungsregeln.</dd></div><div><dt>Enthält die Kids-Seite Werbung?</dt><dd>Nein. Zug in Tierform sendet keine Werbeanfrage und reserviert keinen Werbeplatz.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Ähnliche Spiele</h3><p data-related-intro>Für weitere Beobachtungs- und Zuordnungsaufgaben:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/de/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Sternengedächtnis</strong><span>Merke dir Sterne und Symbole und finde die passenden Paare.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/de/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Lunchbox in Tierfarbe</strong><span>Ordne Lebensmittel nach ihrer natürlichen Farbe der passenden Box zu.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"de\" data-runtime-localize=\"off\"><h3 data-compare-title>Ähnliches Formen-Spiel für Kinder</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color von RV AppStudios LLC trainiert ebenfalls Formerkennung und Zuordnung; die offizielle App-Store-Beschreibung nennt Aktivitäten, bei denen Formen passenden Umrissen zugeordnet werden. Zug in Tierform setzt diese visuelle Entscheidung in einer Kampagne mit 30 Routen ein: sechs Fahrgastformen führen von direkter Zuordnung über Umriss-Waggons und wechselnde Waggonreihenfolgen zu Gedächtnisaufgaben und einer Boarding-Regel, bei der zuerst der Fahrgast gewählt wird. Alle fünf Routen gibt es einen Schaffner-Check. Es gibt keinen Countdown und keine Leben; Sterne und die höchste freigeschaltete Route bleiben nur in diesem Browser.</p><p data-compare-disclaimer>Zug in Tierform ist ein unabhängig entwickeltes WeightPlay-Spiel und keine offizielle Version von Colors &amp; Shapes - Learn Color. WeightPlay ist mit RV AppStudios LLC weder verbunden noch von ihr unterstützt, lizenziert oder gemeinsam entwickelt.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: offizielle App-Store-Seite von Colors &amp; Shapes - Learn Color</a></p></article></section>",
  "it": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Informazioni su Treno a forma di\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">Guida ai giochi bambini di WeightPlay</span><h2 data-wp-game-title data-runtime-localize=\"off\">Treno a forma di</h2><p>Treno a forma di è un gioco di abbinamento bilingue gratuito per bambini con 30 percorsi salvati e sei controlli del conduttore. Gli amici delle forme aspettano in una stazione allegra mentre il giocatore trova il vagone con lo stesso simbolo del cerchio, quadrato, triangolo, stella, diamante o cuore. I percorsi di apertura sono corrispondenze di immagini dirette. I capitoli successivi riducono il colore, spostano l&#39;ordine delle auto dopo ogni imbarco, nascondono brevemente il passeggero o richiedono che il passeggero venga selezionato prima che un&#39;auto possa accettare il biglietto. La Percorso 30 combina tutte queste regole con tutte e sei le auto. Non esiste conto alla rovescia, limite di vita, acquisto, account, richiesta pubblicitaria o penalità che termina un percorso.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>abbinamento di forme</span><span>riconoscimento dei contorni</span><span>memoria visiva</span><span>imbarco in sequenza</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Gioco</span><strong>Ordinamento delle forme</strong></div><div class=\"game-info-fact\"><span>Genere</span><strong>Prescolare · Istruzione · Animali</strong></div><div class=\"game-info-fact\"><span>Difficoltà</span><strong>Facile</strong></div><div class=\"game-info-fact\"><span>Tempo stimato</span><strong>2-5 minuti per tratta</strong></div><div class=\"game-info-fact\"><span>Abilità</span><strong>Riconoscimento del colore · Logica · Coordinazione occhio-mano</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Mondo e missione</h3><p>La Linea delle Forme collega sei piccole stazioni in cui gli amici animali portano pacchi con simboli geometrici ben visibili. Ogni vagone arancione ha una finestra con la forma corrispondente. Il giocatore è il giovane capotreno che controlla il simbolo e manda ogni passeggero nel vagone giusto. La tratta si completa quando tutti gli amici in attesa sono saliti e il treno può partire.</p>\n<p>Le regole del percorso rappresentano le parti più trafficate della ferrovia. Outline Le auto viaggiano attraverso la nebbia che rimuove la maggior parte del colore. Le Switching Car arrivano su piattaforme mobili. Ricorda che le tratte passeggeri abbassano brevemente la carta della stazione, mentre le tratte con carta d&#39;imbarco richiedono un controllo del passeggero prima di scegliere un&#39;auto. Completando il Percorso 30 si completa l&#39;ultimo controllo misto del conduttore.</p></div>\n      <div class=\"game-info-section\"><h3>Sistemi di gioco</h3><p>Ogni percorso contiene da quattro a otto passeggeri selezionati tra sei forme reali. Solo un&#39;auto visibile corrisponde al passeggero attuale.</p>\n<p>Una scelta corretta mostra una breve celebrazione in tempo visibile, fa avanzare i progressi e presenta il passeggero successivo. Un&#39;auto sbagliata dà un feedback gentile e lascia disponibile lo stesso passeggero.</p>\n<p>Le auto di contorno riducono il colore, quindi la geometria è importante. Cambiare auto riordina dopo ogni corrispondenza corretta. Ricorda che il Passeggero nasconde il simbolo ma consente la rivelazione senza penalità. La carta d&#39;imbarco richiede che il passeggero venga selezionato per primo.</p>\n<p>Nessun tentativo assegna tre stelle, un numero piccolo ne assegna due e i tentativi aggiuntivi ne assegnano uno. Il rapporto abilità risultato utilizza partite effettive, primi tentativi, tentativi e passeggeri imbarcati.</p>\n<p>Le stelle e lo sblocco più alto rimangono solo in questo browser. Non sono presenti account, classifiche, acquisti, richieste pubblicitarie, misuratore di vita o conto alla rovescia.</p>\n<p>Ogni quinto percorso è un controllo del conduttore. La Percorso 30 salva il risultato finale e non espone la Percorso 31.</p></div>\n      <div class=\"game-info-section\"><h3>Come si gioca</h3><ol><li>Premi Avvia partita e fai scorrere la guida del percorso orizzontale su una carta sbloccata.</li><li>Leggi la regola del percorso e osserva la sagoma dei passeggeri nella scheda della stazione inferiore.</li><li>Tocca il passeggero, quindi scegli il vagone con lo stesso simbolo; sono supportati anche il trascinamento, il mouse e la tastiera.</li><li>Sui percorsi della memoria, richiama il simbolo nascosto o tocca il passeggero per rivelarlo di nuovo.</li><li>Sali a bordo di ogni passeggero elencato per salvare le stelle e sbloccare esattamente il percorso successivo.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Consigli strategici</h3><ul><li>Pronuncia il nome della forma prima di scegliere un&#39;auto.</li><li>Confronta punti e bordi curvi quando le auto di contorno rimuovono il colore.</li><li>Scansiona nuovamente l&#39;intera traccia dopo ogni partita su un percorso in movimento.</li><li>Per il gioco di memoria, nomina il simbolo ad alta voce o tracciane il contorno nell&#39;aria.</li><li>Sulle rotte carta d'imbarco, seleziona il passeggero prima di toccare un&#39;auto.</li><li>Una scelta sbagliata mantiene aperta la strada, quindi fermati e confronta invece di indovinare rapidamente.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Progressione e difficoltà</h3><p>I percorsi 1–5 insegnano il confronto diretto con da due a quattro auto luminose e terminano al primo controllo del conduttore.</p>\n<p>I percorsi 6–10 utilizzano le vagoni con contorno, rendendo le curve, gli angoli e i punti più importanti del colore.</p>\n<p>Le rotte 11–15 utilizzano il cambio di auto che si riordina dopo un imbarco riuscito.</p>\n<p>Le rotte 16–20 nascondono brevemente il passeggero; toccandolo ripristina la stessa forma senza penalità.</p>\n<p>Le rotte 21–25 aggiungono l&#39;azione ordinata della Carta d&#39;Imbarco prima della corrispondenza della forma.</p>\n<p>I percorsi 26–30 combinano le regole precedenti. La Percorso 30 utilizza sei auto e otto passeggeri con regole di contorno, movimento, memoria e carta d&#39;imbarco.</p></div>\n      <div class=\"game-info-section\"><h3>Nota di design</h3><p>La difficoltà aumenta modificando ciò che il giocatore osserva invece di ridurre i controlli, aggiungere un timer o nascondere l&#39;area colpita corretta. La corrispondenza diretta stabilisce il vocabolario; contorno, movimento, memoria e selezione ordinata aggiungono ciascuno una decisione comprensibile. Il layout logico fisso si adatta uniformemente su telefono, tablet, desktop e paesaggi brevi. Le auto e i gettoni supportati da immagini mantengono il gioco visivo, mentre il testo localizzato spiega solo la regola attuale. I ritardi di corrispondenza e di memoria contano il tempo di riproduzione visibile, quindi un cambio di app non può far avanzare silenziosamente il percorso. A differenza di Animal Quiz, non è richiesta alcuna lettura fattuale; a differenza dello Zoo Helper Day, la decisione è basata sull&#39;equivalenza visiva piuttosto che sullo scopo assistenziale. bambini Play non ha alcuna pretesa pubblicitaria, di acquisto, di account, di classificazione o diagnostica.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Nota per i genitori</h3><p>Treno a forma di può supportare conversazioni su cerchi, angoli, punti, corrispondenza visiva, breve richiamo, ordine delle azioni, messa a fuoco e coordinazione occhio-mano. Un adulto può nominare ciascuna forma ad alta voce o chiedere in cosa differiscono due contorni. Le Stelle e il Rapporto Abilità descrivono solo questa sessione di gioco; non sono un voto scolastico, un punteggio del QI, una diagnosi dello sviluppo o un confronto con un altro bambino. I progressi rimangono nel browser corrente e potrebbero scomparire se la memoria locale viene cancellata. Non è richiesto alcun profilo bambino e il percorso Bambini non richiede pubblicità.</p></div>\n      <div class=\"game-info-section\"><h3>Domande frequenti</h3><dl><div><dt>Quanti percorsi ci sono?</dt><dd>Ci sono 30 percorsi salvati in sei capitoli, con controlli del conduttore a 5, 10, 15, 20, 25 e 30.</dd></div><div><dt>Quali forme appaiono?</dt><dd>Il gioco utilizza cerchi, quadrati, triangoli, stelle, diamanti e cuori.</dd></div><div><dt>Perché il passeggero è scomparso?</dt><dd>Ricorda che le rotte passeggeri lo nascondono brevemente. Tocca il passeggero per rivelare nuovamente la stessa forma senza penalità.</dd></div><div><dt>Perché i vagoni del treno si sono spostati?</dt><dd>Cambiando i percorsi delle auto, riordinali dopo una corrispondenza corretta in modo che il giocatore esegua nuovamente la scansione.</dd></div><div><dt>Perché un&#39;auto non accetta la mia scelta?</dt><dd>I percorsi della carta d&#39;imbarco richiedono che il passeggero venga selezionato prima di scegliere un&#39;auto.</dd></div><div><dt>Cosa succede dopo una partita sbagliata?</dt><dd>Lo stesso passeggero rimane disponibile con un feedback gentile.</dd></div><div><dt>I progressi vengono salvati?</dt><dd>Le stelle e il percorso più alto sbloccato vengono memorizzati solo in questo browser; non è richiesto alcun accesso.</dd></div><div><dt>Supporta telefoni e tastiere?</dt><dd>Sì. Tocca, trascina, mouse e tastiera utilizzano le stesse regole di corrispondenza.</dd></div><div><dt>La pagina Bambini contiene annunci?</dt><dd>No. Treno a forma di non crea richieste pubblicitarie o prenotazioni di annunci.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Giochi correlati</h3><p data-related-intro>Per continuare con osservazione e abbinamento:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/it/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Memoria delle stelle</strong><span>Ricorda la posizione di stelle e simboli per trovare le coppie.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/it/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Portapranzo a colori con</strong><span>Abbina gli alimenti al contenitore del loro colore naturale.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"it\" data-runtime-localize=\"off\"><h3 data-compare-title>Riferimento a un gioco di forme simile per bambini</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color di RV AppStudios LLC lavora anch’esso sul riconoscimento e sull’abbinamento delle forme; la descrizione ufficiale su App Store include attività in cui si associano forme e contorni. Treno a forma di porta questa decisione visiva in una campagna di 30 percorsi: sei forme di passeggeri passano dall’abbinamento diretto ai vagoni con contorno, all’ordine variabile dei vagoni, alla memoria e a una regola d’imbarco in cui si seleziona prima il passeggero, con un controllo del conduttore ogni cinque percorsi. Non ci sono conto alla rovescia o vite, e le stelle e il percorso più alto sbloccato restano solo in questo browser.</p><p data-compare-disclaimer>Treno a forma di è un gioco indipendente di WeightPlay, non una versione ufficiale di Colors &amp; Shapes - Learn Color. WeightPlay non è affiliata, approvata, autorizzata o sviluppata congiuntamente con RV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: pagina ufficiale di Colors &amp; Shapes - Learn Color su App Store</a></p></article></section>",
  "ru": "<section class=\"game-page-info game-page-info-static\" aria-label=\"Информация об игре Поезд в форме животного\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">Руководство по детским играм WeightPlay</span><h2 data-wp-game-title data-runtime-localize=\"off\">Поезд в форме животного</h2><p>Поезд в форме животного — это бесплатная двуязычная игра для детей с 30 сохраненными маршрутами и шестью проверками кондуктора. Друзья-формы ждут на веселой станции, пока игрок находит вагон с таким же символом круга, квадрата, треугольника, звезды, ромба или сердца. Открывающие маршруты представляют собой прямые совпадения с картинками. В последующих главах цвет уменьшается, порядок машин перемещается после каждой посадки, ненадолго скрывается пассажир или требуется, чтобы пассажир был выбран до того, как автомобиль сможет принять билет. Маршрут 30 сочетает в себе все эти правила со всеми шестью автомобилями. Здесь нет обратного отсчета, ограничения жизни, покупки, учетной записи, запроса на рекламу или штрафа, завершающего маршрут.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>сопоставление фигур</span><span>распознавание контуров</span><span>зрительная память</span><span>посадка по порядку</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>Геймплей</span><strong>Сортировка фигур</strong></div><div class=\"game-info-fact\"><span>Жанр</span><strong>Дошкольный · Образование · Животные</strong></div><div class=\"game-info-fact\"><span>Сложность</span><strong>Легко</strong></div><div class=\"game-info-fact\"><span>Примерное время</span><strong>2-5 минут на маршрут</strong></div><div class=\"game-info-fact\"><span>Навыки</span><strong>Распознавание цвета · Логика · Координация рук и глаз</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>Мир и цель</h3><p>Линия фигур соединяет шесть небольших станций, куда друзья-животные приносят яркие посылки с четкими символами. На окне каждого оранжевого вагона есть соответствующая фигура. Игрок выступает юным кондуктором: проверяет символ и отправляет пассажира в нужный вагон. Маршрут завершен, когда все ожидающие друзья безопасно сели и поезд может отправляться.</p>\n<p>Правила маршрута представляют наиболее загруженные участки железной дороги. Схема Автомобили едут сквозь туман, который удаляет большую часть цвета. Машины переключения прибывают на движущиеся платформы. Помните, что пассажирские маршруты ненадолго опускают карточку станции, а маршруты с посадочным талоном требуют проверки пассажира перед выбором автомобиля. Очистка Маршрута 30 завершает последнюю проверку смешанного проводника.</p></div>\n      <div class=\"game-info-section\"><h3>Игровые системы</h3><p>Каждый маршрут содержит от четырех до восьми пассажиров, выбранных из шести реальных фигур. Только одна видимая машина соответствует текущему пассажиру.</p>\n<p>Правильный выбор показывает короткое, видимое по времени празднование, ускоряет прогресс и представляет следующего пассажира. Неправильная машина дает мягкую обратную связь и оставляет в распоряжении того же пассажира.</p>\n<p>Контурные автомобили уменьшают цвет, поэтому геометрия имеет значение. Переключение машин меняет порядок после каждого правильного совпадения. Помните, что Пассажир скрывает символ, но позволяет его раскрыть без штрафа. Посадочный талон требует, чтобы сначала был выбран пассажир.</p>\n<p>За нулевые попытки присуждаются три звезды, за небольшое количество — две, а за дополнительные попытки — одну. В отчете о результатах навыков используются фактические совпадения, первые попытки, повторные попытки и посаженные пассажиры.</p>\n<p>Звезды и высший анлок остаются только в этом браузере. Здесь нет аккаунта, таблицы лидеров, покупки, запроса на рекламу, счетчика жизни или обратного отсчета.</p>\n<p>Каждый пятый маршрут – это проверка кондуктора. Маршрут 30 сохраняет окончательный результат и не отображает Маршрут 31.</p></div>\n      <div class=\"game-info-section\"><h3>Как играть</h3><ol><li>Нажмите «Начать игру» и проведите по горизонтальной направляющей к разблокированной карте.</li><li>Прочтите правила маршрута и посмотрите на фигуру пассажира на нижней карточке станции.</li><li>Нажмите на пассажира, затем выберите вагон с тем же символом; перетаскивание, мышь и клавиатура также поддерживаются.</li><li>На маршрутах памяти вспомните скрытый символ или коснитесь пассажира, чтобы открыть его снова.</li><li>Садитесь на борт каждого пассажира из списка, чтобы накопить звезды и открыть следующий маршрут.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>Советы</h3><ul><li>Прежде чем выбрать машину, произнесите название фигуры.</li><li>Сравните точки и изогнутые края, когда контурные автомобили удаляют цвет.</li><li>Сканируйте всю трассу заново после каждого совпадения на движущемся маршруте.</li><li>Для игры на память назовите символ вслух или обведите его контур в воздухе.</li><li>На маршрутах с посадочным талоном выберите пассажира, прежде чем прикасаться к автомобилю.</li><li>Неправильный выбор оставляет путь открытым, поэтому сделайте паузу и сравните, вместо того чтобы быстро гадать.</li></ul></div>\n      <div class=\"game-info-section\"><h3>Прогресс и сложность</h3><p>Маршруты 1–5 обучают прямому совпадению с двумя-четырьмя яркими машинами и заканчиваются первой проверкой кондуктора.</p>\n<p>На маршрутах 6–10 используются контурные автомобили, поэтому кривые, углы и точки важнее цвета.</p>\n<p>На маршрутах 11–15 используются сменные вагоны, порядок которых меняется после успешной посадки.</p>\n<p>Маршруты 16–20 ненадолго скрывают пассажира; нажатие на него восстанавливает ту же форму без штрафа.</p>\n<p>Маршруты 21–25 добавляют действие заказанного посадочного талона перед совпадением формы.</p>\n<p>Маршруты 26–30 объединяют предыдущие правила. На маршруте 30 используются шесть автомобилей и восемь пассажиров с правилами контура, движения, памяти и посадочного талона.</p></div>\n      <div class=\"game-info-section\"><h3>Заметка разработчика</h3><p>Сложность возрастает за счет изменения того, что наблюдает игрок, вместо уменьшения элементов управления, добавления таймера или сокрытия правильной области попадания. Прямое сопоставление расширяет словарный запас; контур, движение, память и упорядоченный выбор — каждое добавляет по одному понятному решению. Фиксированный логический макет равномерно масштабируется на телефоне, планшете, настольном компьютере и в альбомной ориентации. Машины и жетоны с изображением делают игру визуально визуальной, а локализованный текст поясняет только текущее правило. Задержки совпадения и памяти учитывают видимое время игры, поэтому переключение приложений не может бесшумно продвинуться по маршруту. В отличие от викторины о животных, никакого фактического чтения не требуется; в отличие от Дня помощника зоопарка, решение основано на визуальной эквивалентности, а не на целях ухода. Детская игра не имеет рекламных, покупательских, учетных записей, рейтингов или диагностических претензий.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>Для родителей</h3><p>Поезд в форме животных может поддерживать беседы о кругах, углах, точках, визуальном сопоставлении, кратком вспоминании, порядке действий, фокусировке и зрительно-моторной координации. Взрослый может назвать вслух каждую фигуру или спросить, чем отличаются два контура. Звезды и отчет о навыках описывают только эту игровую сессию; это не школьная оценка, показатель IQ, диагностика развития или сравнение с другим ребенком. Прогресс остается в текущем браузере и может исчезнуть, если локальное хранилище будет очищено. Детский профиль не требуется, а детский маршрут не требует рекламы.</p></div>\n      <div class=\"game-info-section\"><h3>Частые вопросы</h3><dl><div><dt>Сколько маршрутов в игре?</dt><dd>В шести главах сохранено 30 маршрутов с проверками кондуктора на позициях 5, 10, 15, 20, 25 и 30.</dd></div><div><dt>Какие фигуры появляются?</dt><dd>В игре используются круги, квадраты, треугольники, звезды, ромбы и сердечки.</dd></div><div><dt>Почему пассажир исчез?</dt><dd>Помните, что пассажирские маршруты ненадолго скрывают это. Коснитесь пассажира, чтобы снова открыть ту же форму без штрафа.</dd></div><div><dt>Почему вагоны поезда двинулись с места?</dt><dd>Маршруты переключения машин меняют их порядок после правильного совпадения, чтобы игрок снова сканировал.</dd></div><div><dt>Почему машина не примет мой выбор?</dt><dd>Маршруты с посадочными талонами требуют, чтобы пассажир был выбран перед выбором автомобиля.</dd></div><div><dt>Что происходит после неправильного матча?</dt><dd>Тот же пассажир остается доступным с мягкой обратной связью.</dd></div><div><dt>Сохраняется ли прогресс?</dt><dd>Звезды и самый высокий разблокированный маршрут сохраняются только в этом браузере; вход в систему не требуется.</dd></div><div><dt>Поддерживает ли он телефоны и клавиатуры?</dt><dd>Да. Касание, перетаскивание, мышь и клавиатура используют одни и те же правила сопоставления.</dd></div><div><dt>Содержит ли страница «Дети» рекламу?</dt><dd>Нет. Поезд в форме животного не создает рекламных запросов или рекламных резервов.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>Похожие игры</h3><p data-related-intro>Чтобы продолжить наблюдать и сопоставлять:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/ru/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>Звездная память животных</strong><span>Запоминайте расположение звезд и символов и находите пары.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/ru/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>Ланчбокс цвета животного</strong><span>Сопоставляйте продукты с коробкой их естественного цвета.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"ru\" data-runtime-localize=\"off\"><h3 data-compare-title>Похожая игра на сопоставление фигур для детей</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>Colors &amp; Shapes - Learn Color от RV AppStudios LLC тоже развивает распознавание и сопоставление фигур; в официальном описании App Store упомянуты задания на сопоставление фигур с контурами. Поезд в форме животного переносит такое визуальное решение в кампанию из 30 маршрутов: шесть форм пассажиров переходят от прямого совпадения к контурным вагонам, меняющемуся порядку вагонов, заданиям на память и правилу посадки, где сначала выбирают пассажира. Каждые пять маршрутов проходит проверка кондуктора. Таймера и жизней нет, а звезды и самый высокий открытый маршрут сохраняются только в этом браузере.</p><p data-compare-disclaimer>Поезд в форме животного — независимая игра WeightPlay, а не официальная версия Colors &amp; Shapes - Learn Color. WeightPlay не связана с RV AppStudios LLC, не одобрена и не лицензирована ею и не занимается совместной разработкой с ней.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: официальная страница Colors &amp; Shapes - Learn Color в App Store</a></p></article></section>",
  "hi": "<section class=\"game-page-info game-page-info-static\" aria-label=\"आकार ट्रेन गेम की जानकारी\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">WeightPlay बच्चों गेम गाइड</span><h2 data-wp-game-title data-runtime-localize=\"off\">आकार ट्रेन</h2><p>एनिमल शेप ट्रेन 30 सहेजे गए मार्गों और छह कंडक्टर चेक के साथ एक निःशुल्क द्विभाषी किड्स मैचिंग गेम है। आकार के मित्र एक हर्षित स्टेशन पर प्रतीक्षा करते हैं जबकि खिलाड़ी को उसी वृत्त, वर्ग, त्रिकोण, सितारा, हीरे या दिल के प्रतीक के साथ ट्रेन कार मिलती है। आरंभिक मार्ग सीधे चित्र मिलान हैं। बाद के अध्यायों में रंग कम करना, प्रत्येक बोर्डिंग के बाद कार ऑर्डर को स्थानांतरित करना, यात्री को संक्षेप में छिपाना, या कार द्वारा टिकट स्वीकार करने से पहले यात्री का चयन करना आवश्यक है। रूट 30 उन सभी नियमों को सभी छह कारों के साथ जोड़ता है। कोई उलटी गिनती, जीवन सीमा, खरीदारी, खाता, विज्ञापन अनुरोध या जुर्माना नहीं है जो किसी मार्ग को समाप्त करता है।</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>आकार मिलान</span><span>रूपरेखा पहचान</span><span>दृश्य स्मृति</span><span>क्रमबद्ध चढ़ाई</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>गेमप्ले</span><strong>आकार छँटाई</strong></div><div class=\"game-info-fact\"><span>शैली</span><strong>पूर्वस्कूली · शिक्षा · पशु</strong></div><div class=\"game-info-fact\"><span>कठिनाई</span><strong>आसान</strong></div><div class=\"game-info-fact\"><span>अनुमानित समय</span><strong>प्रति रूट 2-5 मिनट</strong></div><div class=\"game-info-fact\"><span>अभ्यास कौशल</span><strong>रंग पहचान · तर्क · हाथ-आँख समन्वय</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>दुनिया और लक्ष्य</h3><p>आकार लाइन छह छोटे स्टेशनों को जोड़ती है, जहाँ पशु मित्र साफ़ आकार-चिह्न वाले रंगीन पैकेट लेकर आते हैं। हर नारंगी डिब्बे की खिड़की पर उससे मेल खाता आकार होता है। खिलाड़ी छोटे कंडक्टर की भूमिका में चिह्न जाँचकर हर यात्री को सही डिब्बे में भेजता है। जब सभी प्रतीक्षारत मित्र सुरक्षित चढ़ जाते हैं, मार्ग पूरा होता है और ट्रेन चल सकती है।</p>\n<p>मार्ग नियम रेलवे के व्यस्त हिस्सों का प्रतिनिधित्व करते हैं। आउटलाइन कारें कोहरे में यात्रा करती हैं जिससे अधिकांश रंग निकल जाते हैं। स्विचिंग कारें चलती प्लेटफार्मों पर आती हैं। याद रखें यात्री मार्गों पर स्टेशन कार्ड को संक्षेप में कम किया जाता है, जबकि बोर्डिंग पास मार्गों के लिए कार चुनने से पहले यात्री की जांच की आवश्यकता होती है। क्लियरिंग रूट 30 अंतिम मिश्रित कंडक्टर जाँच को पूरा करता है।</p></div>\n      <div class=\"game-info-section\"><h3>गेम सिस्टम</h3><p>प्रत्येक मार्ग में छह वास्तविक आकृतियों में से चुने गए चार से आठ यात्री होते हैं। केवल एक दृश्यमान कार वर्तमान यात्री से मेल खाती है।</p>\n<p>एक सही विकल्प कम दृश्य-समय का उत्सव दिखाता है, प्रगति को आगे बढ़ाता है और अगले यात्री को प्रस्तुत करता है। एक गलत कार सौम्य प्रतिक्रिया देती है और उसी यात्री को उपलब्ध छोड़ देती है।</p>\n<p>आउटलाइन कारें रंग कम करती हैं इसलिए ज्यामिति मायने रखती है। प्रत्येक सही मिलान के बाद स्विचिंग कारों को पुनः व्यवस्थित करें। याद रखें यात्री प्रतीक को छुपाता है लेकिन बिना किसी दंड के प्रकटीकरण की अनुमति देता है। बोर्डिंग पास के लिए पहले यात्री का चयन करना जरूरी है।</p>\n<p>शून्य पुनर्प्रयास को तीन स्टार, छोटी संख्या को दो पुरस्कार और अतिरिक्त पुनर्प्रयास को एक पुरस्कार मिलता है। परिणाम कौशल रिपोर्ट वास्तविक मिलान, पहले प्रयास, पुनः प्रयास और बोर्डिंग यात्रियों का उपयोग करती है।</p>\n<p>सितारे और उच्चतम अनलॉक केवल इस ब्राउज़र में रहते हैं। कोई खाता, लीडरबोर्ड, खरीदारी, विज्ञापन अनुरोध, जीवन मीटर या उलटी गिनती नहीं है।</p>\n<p>प्रत्येक पाँचवाँ मार्ग एक कंडक्टर जाँच है। रूट 30 अंतिम परिणाम सहेजता है और कोई रूट 31 उजागर नहीं करता है।</p></div>\n      <div class=\"game-info-section\"><h3>कैसे खेलें</h3><ol><li>स्टार्ट गेम दबाएं और क्षैतिज रूट रेल को अनलॉक किए गए कार्ड पर स्वाइप करें।</li><li>मार्ग नियम पढ़ें और निचले स्टेशन कार्ड में यात्री आकृति देखें।</li><li>यात्री को टैप करें, फिर उसी प्रतीक के साथ ट्रेन कार चुनें; ड्रैग, माउस और कीबोर्ड भी समर्थित हैं।</li><li>स्मृति मार्गों पर, छिपे हुए प्रतीक को याद करें या इसे फिर से प्रकट करने के लिए यात्री को टैप करें।</li><li>सितारों को बचाने और अगले मार्ग को अनलॉक करने के लिए प्रत्येक सूचीबद्ध यात्री पर चढ़ें।</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>रणनीति संकेत</h3><ul><li>कार चुनने से पहले आकार का नाम बताएं.</li><li>जब आउटलाइन कारें रंग हटाती हैं तो बिंदुओं और घुमावदार किनारों की तुलना करें।</li><li>प्रत्येक मैच के बाद चलते हुए मार्ग पर पूरे ट्रैक को फिर से स्कैन करें।</li><li>मेमोरी प्ले के लिए, प्रतीक को ज़ोर से नाम दें या हवा में उसकी रूपरेखा बनाएं।</li><li>बोर्डिंग पास मार्गों पर, कार को छूने से पहले यात्री का चयन करें।</li><li>एक गलत विकल्प रास्ता खुला रखता है, इसलिए तुरंत अनुमान लगाने के बजाय रुकें और तुलना करें।</li></ul></div>\n      <div class=\"game-info-section\"><h3>प्रगति और कठिनाई</h3><p>रूट 1-5 दो से चार चमकदार कारों के साथ सीधा मिलान सिखाते हैं और पहले कंडक्टर चेक पर समाप्त होते हैं।</p>\n<p>रूट 6-10 आउटलाइन कारों का उपयोग करते हैं, जिससे मोड़, कोने और बिंदु रंग से अधिक महत्वपूर्ण हो जाते हैं।</p>\n<p>रूट 11-15 स्विचिंग कारों का उपयोग करते हैं जो सफल बोर्डिंग के बाद पुन: व्यवस्थित हो जाती हैं।</p>\n<p>मार्ग 16-20 यात्री को संक्षेप में छिपाते हैं; इसे टैप करने से बिना किसी जुर्माने के वही आकार वापस आ जाता है।</p>\n<p>रूट 21-25 आकार मिलान से पहले आदेशित बोर्डिंग पास कार्रवाई जोड़ते हैं।</p>\n<p>रूट 26-30 पूर्व नियमों को जोड़ते हैं। रूट 30 रूपरेखा, संचलन, मेमोरी और बोर्डिंग पास नियमों के साथ छह कारों और आठ यात्रियों का उपयोग करता है।</p></div>\n      <div class=\"game-info-section\"><h3>डिज़ाइन नोट</h3><p>नियंत्रण को छोटा करने, टाइमर जोड़ने या सही हिट क्षेत्र को छिपाने के बजाय खिलाड़ी जो देखता है उसे बदलने से कठिनाई बढ़ती है। सीधा मिलान शब्दावली स्थापित करता है; रूपरेखा, गति, स्मृति और क्रमबद्ध चयन प्रत्येक एक समझने योग्य निर्णय जोड़ते हैं। निश्चित तार्किक लेआउट फोन, टैबलेट, डेस्कटॉप और लघु परिदृश्य पर समान रूप से स्केल करता है। छवि-समर्थित कारें और टोकन दृश्य को बनाए रखते हैं, जबकि स्थानीयकृत पाठ केवल वर्तमान नियम की व्याख्या करता है। मैच और मेमोरी विलंब दृश्यमान प्लेटाइम की गणना करते हैं, इसलिए ऐप स्विच चुपचाप मार्ग को आगे नहीं बढ़ा सकता है। पशु प्रश्नोत्तरी के विपरीत, किसी तथ्यात्मक पढ़ने की आवश्यकता नहीं है; ज़ू हेल्पर डे के विपरीत, निर्णय देखभाल के उद्देश्य के बजाय दृश्य तुल्यता है। किड्स प्ले का कोई विज्ञापन, खरीदारी, खाता, रैंकिंग या निदान संबंधी दावा नहीं है।</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>अभिभावक सूचना</h3><p>एनिमल शेप ट्रेन वृत्तों, कोनों, बिंदुओं, दृश्य मिलान, लघु स्मरण, क्रिया क्रम, फोकस और हाथ-आँख समन्वय के बारे में बातचीत का समर्थन कर सकती है। एक वयस्क प्रत्येक आकृति का नाम ज़ोर से बता सकता है या पूछ सकता है कि दो रूपरेखाएँ किस प्रकार भिन्न हैं। सितारे और कौशल रिपोर्ट केवल इस खेल सत्र का वर्णन करते हैं; वे स्कूल ग्रेड, आईक्यू स्कोर, विकासात्मक निदान या किसी अन्य बच्चे के साथ तुलना नहीं हैं। प्रगति वर्तमान ब्राउज़र में रहती है और स्थानीय संग्रहण साफ़ होने पर गायब हो सकती है। किसी चाइल्ड प्रोफ़ाइल की आवश्यकता नहीं है, और किड्स रूट किसी विज्ञापन का अनुरोध नहीं करता है।</p></div>\n      <div class=\"game-info-section\"><h3>अक्सर पूछे गए प्रश्न</h3><dl><div><dt>कितने मार्ग हैं?</dt><dd>छह अध्यायों में 30 सहेजे गए मार्ग हैं, जिनमें 5, 10, 15, 20, 25 और 30 पर कंडक्टर चेक हैं।</dd></div><div><dt>कौन सी आकृतियाँ दिखाई देती हैं?</dt><dd>खेल में वृत्त, वर्ग, त्रिकोण, तारे, हीरे और दिल का उपयोग किया जाता है।</dd></div><div><dt>यात्री क्यों गायब हो गया?</dt><dd>याद रखें यात्री मार्ग इसे संक्षेप में छुपाते हैं। बिना किसी दंड के फिर से उसी आकृति को प्रकट करने के लिए यात्री को टैप करें।</dd></div><div><dt>रेल गाड़ियाँ क्यों चलती थीं?</dt><dd>कारों के रूट बदलने से सही मिलान के बाद उन्हें पुन: व्यवस्थित किया जाता है ताकि खिलाड़ी फिर से स्कैन कर सके।</dd></div><div><dt>कोई कार मेरी पसंद को स्वीकार क्यों नहीं करेगी?</dt><dd>बोर्डिंग पास मार्गों के लिए यात्री को कार चुनने से पहले चयन करना आवश्यक है।</dd></div><div><dt>गलत मिलान के बाद क्या होता है?</dt><dd>वही यात्री सौम्य फीडबैक के साथ उपलब्ध रहता है।</dd></div><div><dt>क्या प्रगति सहेजी जाती है?</dt><dd>सितारे और उच्चतम अनलॉक मार्ग केवल इस ब्राउज़र में संग्रहीत हैं; कोई लॉगिन आवश्यक नहीं है.</dd></div><div><dt>क्या यह फ़ोन और कीबोर्ड का समर्थन करता है?</dt><dd>हाँ. स्पर्श, खींचें, माउस और कीबोर्ड समान मिलान नियमों का उपयोग करते हैं।</dd></div><div><dt>क्या किड्स पेज में विज्ञापन हैं?</dt><dd>नहीं, एनिमल शेप ट्रेन कोई विज्ञापन अनुरोध या विज्ञापन आरक्षित नहीं बनाता है।</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>संबंधित खेल</h3><p data-related-intro>अवलोकन और मिलान का अभ्यास जारी रखने के लिए:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/hi/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>स्टार मेमोरी</strong><span>सितारों और प्रतीकों की जगह याद करके जोड़े खोजें।</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/hi/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>रंग लंचबॉक्स</strong><span>भोजन को उसके प्राकृतिक रंग वाले सही लंचबॉक्स से मिलाएँ।</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"hi\" data-runtime-localize=\"off\"><h3 data-compare-title>बच्चों के लिए मिलता-जुलता आकार-मिलान संदर्भ</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>RV AppStudios LLC का Colors &amp; Shapes - Learn Color भी आकार पहचान और मिलान पर केंद्रित है; आधिकारिक App Store विवरण में आकारों को उनकी रूपरेखाओं से मिलाने वाली गतिविधियाँ दी गई हैं। आकार ट्रेन इसी दृश्य निर्णय को 30 मार्गों की ट्रेन यात्रा में रखता है: छह यात्री आकार सीधे मिलान से रूपरेखा डिब्बों, बदलते डिब्बा क्रम, स्मृति मार्गों और पहले यात्री चुनने वाली चढ़ाई प्रक्रिया तक बढ़ते हैं, और हर पाँच मार्ग पर कंडक्टर चेक होता है। कोई उलटी गिनती या जीवन सीमा नहीं है, और सितारे तथा सबसे ऊँचा खुला मार्ग केवल इसी ब्राउज़र में सहेजे जाते हैं।</p><p data-compare-disclaimer>आकार ट्रेन WeightPlay द्वारा स्वतंत्र रूप से बनाया गया खेल है, Colors &amp; Shapes - Learn Color का आधिकारिक संस्करण नहीं। WeightPlay का RV AppStudios LLC के साथ कोई संबद्धता, समर्थन, लाइसेंस या संयुक्त विकास संबंध नहीं है।</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: Colors &amp; Shapes - Learn Color की आधिकारिक App Store सूची</a></p></article></section>",
  "ar": "<section class=\"game-page-info game-page-info-static\" aria-label=\"معلومات لعبة قطار على شكل حيوان\">\n\n    <div class=\"game-info-hero\">\n      <div class=\"game-info-title\"><span class=\"game-info-kicker\">دليل ألعاب WeightPlay للأطفال</span><h2 data-wp-game-title data-runtime-localize=\"off\">قطار على شكل حيوان</h2><p>قطار على شكل حيوان هي لعبة مطابقة مجانية ثنائية اللغة للأطفال تحتوي على 30 مسارًا محفوظًا وستة عمليات فحص للموصلات. ينتظر أصدقاء الشكل في محطة مبهجة بينما يجد اللاعب سيارة القطار التي تحمل نفس رمز الدائرة أو المربع أو المثلث أو النجمة أو الماس أو القلب. الطرق الافتتاحية عبارة عن تطابقات صورية مباشرة. تقلل الفصول اللاحقة اللون، أو تنقل أمر السيارة بعد كل صعود، أو تخفي الراكب لفترة وجيزة، أو تطلب تحديد الراكب قبل أن تتمكن السيارة من قبول التذكرة. يجمع الطريق 30 كل هذه القواعد مع جميع السيارات الست. لا يوجد عد تنازلي، أو حد للحياة، أو شراء، أو حساب، أو طلب إعلان، أو عقوبة تنهي المسار.</p></div>\n      <div class=\"game-info-tags\" data-shape-train-tags data-wp-gameplay-tags=\"1.3.0\"><span>مطابقة الأشكال</span><span>تمييز الحدود</span><span>الذاكرة البصرية</span><span>صعود بالترتيب</span></div><div class=\"game-info-facts\"><div class=\"game-info-fact\"><span>طريقة اللعب</span><strong>فرز الشكل</strong></div><div class=\"game-info-fact\"><span>النوع</span><strong>مرحلة ما قبل المدرسة · التعليم · حيوانات</strong></div><div class=\"game-info-fact\"><span>الصعوبة</span><strong>سهل</strong></div><div class=\"game-info-fact\"><span>وقت اللعب المقدر</span><strong>2-5 دقائق لكل طريق</strong></div><div class=\"game-info-fact\"><span>المهارات المتدرّبة</span><strong>التعرف على اللون · المنطق · التنسيق بين اليد والعين</strong></div></div>\n    </div>\n\n    <div class=\"game-info-sections\">\n      <div class=\"game-info-section\"><h3>العالم والرسالة</h3><p>يربط خط الأشكال ست محطات صغيرة يصل إليها أصدقاء الحيوانات ومعهم طرود ملوّنة تحمل رموز أشكال واضحة. تحمل نافذة كل عربة برتقالية الشكل المطابق. يلعب الطفل دور الموصل الصغير، فيفحص الرمز ويرسل كل راكب إلى العربة الصحيحة. يكتمل المسار عندما يصعد جميع الأصدقاء المنتظرين بأمان ويصبح القطار جاهزًا للانطلاق.</p>\n<p>تمثل قواعد المسار الأجزاء الأكثر ازدحامًا في السكك الحديدية. تسافر السيارات عبر الضباب الذي يزيل معظم الألوان. تصل سيارات التبديل على منصات متحركة. تذكر أن مسارات الركاب تخفض بطاقة المحطة لفترة وجيزة، بينما تتطلب مسارات بطاقة الصعود فحص الركاب قبل اختيار السيارة. يكمل مسح الطريق 30 فحص الموصل المختلط النهائي.</p></div>\n      <div class=\"game-info-section\"><h3>كيف تعمل الأنظمة</h3><p>يحتوي كل طريق على أربعة إلى ثمانية ركاب يتم اختيارهم من بين ستة أشكال حقيقية. هناك سيارة واحدة مرئية فقط تتطابق مع الراكب الحالي.</p>\n<p>يُظهر الاختيار الصحيح احتفالًا قصيرًا بالوقت المرئي، ويعزز التقدم ويقدم الراكب التالي. السيارة الخاطئة تعطي ردود فعل لطيفة وتترك نفس الراكب متاحًا.</p>\n<p>تعمل سيارات Outline على تقليل الألوان لذا فإن الهندسة مهمة. يتغير ترتيب تبديل السيارات بعد كل مباراة صحيحة. تذكر أن الراكب يخفي الرمز ولكنه يسمح بالكشف بدون عقوبة. تتطلب بطاقة الصعود إلى الطائرة أن يتم اختيار الراكب أولاً.</p>\n<p>تمنح المحاولات الصفرية ثلاث نجوم، بينما يمنح العدد الصغير نجمتين، وتمنح المحاولات الإضافية نجمة واحدة. يستخدم تقرير المهارات الناتج المطابقات الفعلية والمحاولات الأولى وإعادة المحاولة والركاب الصاعدين.</p>\n<p>النجوم وأعلى فتح تبقى فقط في هذا المتصفح. لا يوجد حساب أو لوحة صدارة أو شراء أو طلب إعلان أو مقياس حياة أو عد تنازلي.</p>\n<p>كل طريق خامس هو فحص الموصل. الطريق 30 يحفظ النتيجة النهائية ولا يكشف عن الطريق 31.</p></div>\n      <div class=\"game-info-section\"><h3>طريقة اللعب</h3><ol><li>اضغط على &quot;بدء اللعبة&quot; واسحب شريط المسار الأفقي إلى بطاقة غير مقفلة.</li><li>اقرأ قاعدة الطريق وانظر إلى شكل الراكب في بطاقة المحطة السفلية.</li><li>اضغط على الراكب، ثم اختر عربة القطار التي تحمل نفس الرمز؛ كما يتم دعم السحب والماوس ولوحة المفاتيح.</li><li>في مسارات الذاكرة، تذكر الرمز المخفي أو اضغط على الراكب للكشف عنه مرة أخرى.</li><li>اصعد على متن كل راكب مدرج لحفظ النجوم وفتح المسار التالي بالضبط.</li></ol></div>\n      <div class=\"game-info-section game-info-strategy\"><h3>نصائح استراتيجية</h3><ul><li>قل اسم الشكل قبل اختيار السيارة.</li><li>قارن النقاط والحواف المنحنية عندما تزيل سيارات المخطط التفصيلي اللون.</li><li>قم بمسح المسار بالكامل مرة أخرى بعد كل مباراة على طريق متحرك.</li><li>لتشغيل الذاكرة، قم بتسمية الرمز بصوت عالٍ أو تتبع مخططه في الهواء.</li><li>في مسارات بطاقة الصعود، حدد الراكب قبل لمس السيارة.</li><li>يؤدي الاختيار الخاطئ إلى إبقاء الطريق مفتوحًا، لذا توقف مؤقتًا وقارن بدلاً من التخمين بسرعة.</li></ul></div>\n      <div class=\"game-info-section\"><h3>تطور المراحل والصعوبة</h3><p>تقوم المسارات من 1 إلى 5 بتعليم المطابقة المباشرة مع سيارتين إلى أربع سيارات لامعة وتنتهي عند فحص الموصل الأول.</p>\n<p>تستخدم الطرق من 6 إلى 10 سيارات الخطوط العريضة، مما يجعل المنحنيات والزوايا والنقاط أكثر أهمية من اللون.</p>\n<p>تستخدم الطرق 11-15 تبديل السيارات التي تتغير بعد الصعود الناجح.</p>\n<p>الطرق 16-20 تخفي الراكب لفترة وجيزة. يؤدي النقر عليه إلى استعادة نفس الشكل دون عقوبة.</p>\n<p>تضيف المسارات 21-25 إجراء بطاقة الصعود المطلوبة قبل مطابقة الشكل.</p>\n<p>تجمع الطرق 26-30 بين القواعد السابقة. يستخدم الطريق 30 ست سيارات وثمانية ركاب مع قواعد الخطوط العريضة والحركة والذاكرة وبطاقة الصعود إلى الطائرة.</p></div>\n      <div class=\"game-info-section\"><h3>ملاحظة تصميم المطوّر</h3><p>وتزداد الصعوبة من خلال تغيير ما يلاحظه اللاعب بدلاً من تقليص عناصر التحكم أو إضافة مؤقت أو إخفاء منطقة الضرب الصحيحة. المطابقة المباشرة تحدد المفردات؛ يضيف كل من المخطط التفصيلي والحركة والذاكرة والاختيار المرتب قرارًا واحدًا مفهومًا. يتدرج التخطيط المنطقي الثابت بشكل موحد على الهاتف والجهاز اللوحي وسطح المكتب والمناظر الطبيعية القصيرة. تستمر السيارات والرموز المدعومة بالصور في اللعب بشكل مرئي، بينما يشرح النص المترجم القاعدة الحالية فقط. تحسب تأخيرات المطابقة والذاكرة وقت التشغيل المرئي، لذلك لا يمكن لمفتاح التطبيق التقدم في المسار بصمت. على عكس مسابقة الحيوان، لا يلزم القراءة الواقعية؛ على عكس Zoo Helper Day، فإن القرار هو التكافؤ البصري وليس غرض الرعاية. لا تحتوي لعبة لعب الأطفال على أي إعلان أو شراء أو حساب أو تصنيف أو مطالبة تشخيصية.</p></div>\n      <div class=\"game-info-section game-info-parent\"><h3>ملاحظة للوالدين</h3><p>قد يدعم قطار شكل الحيوان المحادثات حول الدوائر والزوايا والنقاط والمطابقة المرئية والاستدعاء القصير وترتيب الإجراء والتركيز والتنسيق بين اليد والعين. يمكن لأي شخص بالغ تسمية كل شكل بصوت عالٍ أو السؤال عن مدى اختلاف الخطوط العريضة. تصف النجوم وتقرير المهارات جلسة اللعب هذه فقط؛ فهي ليست درجة مدرسية أو درجة الذكاء أو تشخيص النمو أو المقارنة مع طفل آخر. يبقى التقدم في المتصفح الحالي وقد يختفي إذا تم مسح وحدة التخزين المحلية. لا يلزم وجود ملف تعريف خاص بالطفل، ولا يتطلب مسار الأطفال أي إعلانات.</p></div>\n      <div class=\"game-info-section\"><h3>الأسئلة الشائعة</h3><dl><div><dt>كم عدد المسارات؟</dt><dd>هناك 30 طريقًا محفوظًا في ستة فصول، مع عمليات فحص الموصل عند 5 و10 و15 و20 و25 و30.</dd></div><div><dt>ما هي الأشكال التي تظهر؟</dt><dd>تستخدم اللعبة الدوائر والمربعات والمثلثات والنجوم والماس والقلوب.</dd></div><div><dt>لماذا اختفى الراكب؟</dt><dd>تذكر أن مسارات الركاب تخفيها لفترة وجيزة. اضغط على الراكب ليكشف عن نفس الشكل مرة أخرى دون عقوبة.</dd></div><div><dt>لماذا تحركت عربات القطار؟</dt><dd>يقوم تبديل مسارات السيارات بإعادة ترتيبها بعد المطابقة الصحيحة حتى يقوم اللاعب بمسحها مرة أخرى.</dd></div><div><dt>لماذا لن تقبل السيارة خياري؟</dt><dd>تتطلب مسارات بطاقة الصعود إلى الطائرة اختيار الراكب قبل اختيار السيارة.</dd></div><div><dt>ماذا يحدث بعد مباراة خاطئة؟</dt><dd>يظل نفس الراكب متاحًا مع تعليقات لطيفة.</dd></div><div><dt>هل يتم حفظ التقدم؟</dt><dd>يتم تخزين النجوم وأعلى طريق مفتوح فقط في هذا المتصفح؛ لا يلزم تسجيل الدخول.</dd></div><div><dt>هل يدعم الهواتف ولوحات المفاتيح؟</dt><dd>نعم. يستخدم اللمس والسحب والماوس ولوحة المفاتيح نفس قواعد المطابقة.</dd></div><div><dt>هل تحتوي صفحة الأطفال على إعلانات؟</dt><dd>لا، لا يُنشئ قطار على شكل حيوان أي طلب إعلان أو حجز إعلان.</dd></div></dl></div>\n\n    </div>\n  <div class=\"game-info-section\" data-shape-train-related><h3 data-related-title>ألعاب ذات صلة</h3><p data-related-intro>لمتابعة تدريب الملاحظة والمطابقة:</p><div class=\"game-info-related\"><a class=\"game-info-related-card\" data-related-star data-wp-related-id=\"star-memory\" href=\"/ar/games/star-memory/\"><span class=\"game-info-related-copy\"><strong>ذاكرة نجم الحيوان</strong><span>تذكّر مواقع النجوم والرموز للعثور على الأزواج.</span></span></a><a class=\"game-info-related-card\" data-related-lunch data-wp-related-id=\"color-lunchbox\" href=\"/ar/games/color-lunchbox/\"><span class=\"game-info-related-copy\"><strong>صندوق طعام بلون الحيوان</strong><span>طابق الطعام مع صندوق اللون الطبيعي المناسب.</span></span></a></div></div><article class=\"game-info-section\" data-wp-market-comparison=\"1.3.0\" data-comparison-locale=\"ar\" data-runtime-localize=\"off\"><h3 data-compare-title>مرجع للعبة أطفال مشابهة في مطابقة الأشكال</h3><div class=\"game-info-tags\"><span><bdi>Colors &amp; Shapes - Learn Color</bdi></span></div><p data-compare-body>تعمل Colors &amp; Shapes - Learn Color من RV AppStudios LLC أيضًا على تمييز الأشكال ومطابقتها؛ ويذكر وصف App Store الرسمي أنشطة لمطابقة الأشكال مع حدودها. تضع قطار على شكل حيوان هذا القرار البصري داخل حملة من 30 مسارًا: تتدرج ستة أشكال للركاب من المطابقة المباشرة إلى عربات الحدود، وتبديل ترتيب العربات، ومسارات الذاكرة، وقاعدة صعود تتطلب اختيار الراكب أولًا، مع فحص للموصل كل خمسة مسارات. لا يوجد عد تنازلي أو أرواح، وتبقى النجوم وأعلى مسار مفتوح محفوظة في هذا المتصفح فقط.</p><p data-compare-disclaimer>قطار على شكل حيوان لعبة مستقلة من WeightPlay وليست إصدارًا رسميًا من Colors &amp; Shapes - Learn Color. لا توجد علاقة انتساب أو تأييد أو ترخيص أو تطوير مشترك بين WeightPlay وRV AppStudios LLC.</p><p><a data-compare-source href=\"https://apps.apple.com/us/app/colors-shapes-learn-color/id1272085786\" rel=\"noopener noreferrer\">RV AppStudios LLC: صفحة Colors &amp; Shapes - Learn Color الرسمية على App Store</a></p></article></section>"
});

export function applyShapeTrainTextGrowth(html, locale) {
  const section = SHAPE_TRAIN_GUIDE_SECTIONS[locale];
  if (!section) throw new Error(`Missing Shape Train Text Growth locale: ${locale}`);
  const guidePattern = /<section\b[^>]*class=["'][^"']*\bgame-page-info\b[^"']*\bgame-page-info-static\b[^"']*["'][^>]*>[\s\S]*?<\/section>/i;
  if (!guidePattern.test(html)) throw new Error(`Missing Shape Train static Guide section: ${locale}`);
  const withGuide = html.replace(guidePattern, section);
  return withGuide.replace(/(<body\b[^>]*)(>)/i, (whole, opening, closing) => {
    if (/\bdata-wp-game-owned-guide=["']true["']/i.test(opening)) return whole;
    return `${opening} data-wp-game-owned-guide="true"${closing}`;
  });
}
